27	class ResumeDriver
28	{
29	public:
30	  // data0/data1/abstractcs/command are defined once in abstract_command.hpp;
31	  // dmcontrol/dmstatus are run-control registers specific to this driver.
32	  static constexpr uint8_t kData0      = kDmiData0;
33	  static constexpr uint8_t kData1      = kDmiData1;
34	  static constexpr uint8_t kDmcontrol  = 0x10;
35	  static constexpr uint8_t kDmstatus   = 0x11;
36	  static constexpr uint8_t kAbstractcs = kDmiAbstractcs;
37	  static constexpr uint8_t kCommand    = kDmiCommand;
38	
39	  static constexpr uint16_t kCsrDpc      = 0x7B1;
40	  static constexpr uint16_t kCsrDcsr     = 0x7B0;
41	  static constexpr uint16_t kCsrPmpcfg0  = 0x3A0;
42	  static constexpr uint16_t kCsrPmpaddr0 = 0x3B0;
43	  static constexpr uint16_t kCsrFcsr     = 0x003;
44	  static constexpr uint16_t kCsrMstatus  = 0x300;
45	  static constexpr uint16_t kCsrMisa     = 0x301;
46	  static constexpr uint16_t kCsrMedeleg  = 0x302;
47	  static constexpr uint16_t kCsrMideleg  = 0x303;
48	  static constexpr uint16_t kCsrMie      = 0x304;
49	  static constexpr uint16_t kCsrMtvec    = 0x305;
50	  static constexpr uint16_t kCsrMscratch = 0x340;
51	  static constexpr uint16_t kCsrMepc     = 0x341;
52	  static constexpr uint16_t kCsrMcause   = 0x342;
53	  static constexpr uint16_t kCsrMtval    = 0x343;
54	  static constexpr uint16_t kCsrMip      = 0x344;
55	  static constexpr uint16_t kCsrSatp     = 0x180;
56	  static constexpr uint16_t kCsrMcycle   = 0xB00;
57	  static constexpr uint16_t kCsrMinstret = 0xB02;
58	  static constexpr uint16_t kCsrVlenb    = 0xC22;
59	  static constexpr uint16_t kCsrVstart   = 0x008;
60	  static constexpr uint16_t kCsrVxsat    = 0x009;
61	  static constexpr uint16_t kCsrVxrm     = 0x00A;
62	  static constexpr uint16_t kCsrVcsr     = 0x00F;
63	  static constexpr uint16_t kCsrVtype    = 0xC21;
64	  static constexpr uint16_t kCsrVl       = 0xC20;
65	
66	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
67	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
68	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
69	
70	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
71	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
72	
73	  static constexpr uint32_t kAbstractcsBusy        = hybrid::kAbstractcsBusy;
74	  static constexpr uint32_t kAbstractcsCmderrMask  = hybrid::kAbstractcsCmderrMask;
75	
76	  // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
77	  // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
78	  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
79	  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
80	  static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
81	  static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
82	
83	  static constexpr unsigned kPollIterations = kDmiPollIterations;
84	
85	  explicit ResumeDriver(DmiBus& bus)
86	      : bus_{bus}
87	  {}
88	
89	  void resume(const hybrid_state_v1& state)
90	  {
91	    if (state.magic != HYBRID_STATE_MAGIC)
92	      throw std::runtime_error("ResumeDriver::resume: bad magic");
93	    if (state.version != HYBRID_STATE_VERSION)
94	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
95	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
96	    if (state.priv == 2 || state.priv > 3)
97	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
98	
99	    // dmactive must transition 0->1 in its own write before any other
100	    // DMCONTROL bit is honored (RISC-V Debug Spec).
101	    bus_.write(kDmcontrol, kDmcontrolDmactive);
102	    request_halt();
103	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
104	
105	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
106	    // accepted (FS or VS == Off disables the extension and the hart NACKs
107	    // the writes). The drained state.mstatus may legitimately carry FS or
108	    // VS at Off (e.g. an OS context-switched the regs away before the
109	    // trigger fired) -- gating the write on the drained field skips the
110	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
111	    // write mstatus when either extension is in scope; force-OR Initial
112	    // when the drained field is Off. This enable is local to the vsim
113	    // phase; the state.mstatus written to the handoff file is left
114	    // unmodified.
115	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
116	      uint64_t enable_mstatus = state.mstatus;
117	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
118	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
119	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
120	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
121	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
122	    }
123	
124	    // FPR restore (requires mstatus.FS enabled above).
125	    if (state.flags & HYBRID_FLAG_FP) {
126	      for (uint16_t i = 0; i < 32; ++i)
127	        write_64bit_register(regno_fpr(i), state.fpr[i]);
128	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
129	      // fallback scratch x5 is overwritten by the GPR loop below.
130	      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
131	    }
132	
133	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
134	    // the GPR loop overwrites x5 afterward so state is preserved).
135	    if (state.flags & HYBRID_FLAG_V) {
136	      // V data regfile: reload v0..v31 from the shared scratch region via the
137	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
138	      // because the sweep's own vsetvl (e8/m1) clobbers vtype/vl/vstart, which
139	      // the restore then overwrites with the architectural values. The sweep
140	      // uses x5/x6/x7 as scratch (x7 is the base pointer); the GPR loop below
141	      // restores all three. The wire format reserves HYBRID_VLEN_BYTES_MAX per
142	      // register, so that -- not the runtime vlenb -- is the scratch stride.
143	      pb_v_data_sweep(bus_, kVScratchGpa, HYBRID_VLEN_BYTES_MAX, state.vlenb,
144	                      /*load=*/true);
145	
146	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
147	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
148	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
149	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
150	      write_64bit_register(regno_gpr(5), state.vl);
151	      write_64bit_register(regno_gpr(6), state.vtype);
152	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
153	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
154	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
155	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
156	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
157	      write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
158	      write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
159	    }
160	
161	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
162	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
163	    // in the drained privilege; M-mode states skip the write (prv already 3).
164	    // Before the GPR loop: a PB fallback would clobber scratch x5.
165	    if (state.priv != 3) {
166	      // L2 slice: with PMP implemented and no matching entry, every S/U
167	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
168	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
169	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
170	      // RV64. Tolerant writes: entries beyond what the hart implements
171	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
172	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
173	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
174	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
175	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
176	
177	      const uint64_t dcsr =
178	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
179	      write_csr_abstract_or_pb(kCsrDcsr,
180	                               (dcsr & ~uint64_t{0x3}) | state.priv);
181	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
182	      // silently measure the ROI in the wrong privilege. Verify and abort.
183	      const uint64_t got =
184	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
185	        & 0x3u;
186	      if (got != state.priv)
187	        throw std::runtime_error(
188	          "ResumeDriver::resume: engine does not implement privilege level "
189	          + std::to_string(state.priv)
190	          + " (dcsr.prv pinned to " + std::to_string(got)
191	          + "); pick an S/U-capable engine");
192	    }
193	
194	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite).
195	    for (uint16_t i = 1; i < 32; ++i)
196	      write_64bit_register(regno_gpr(i), state.gpr[i]);
197	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
198	
199	    write_csr_tolerant(kCsrMtvec, state.mtvec);
200	
201	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
202	    // from QEMU1's drain value. Without this, vsim's local counter starts
203	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
204	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
205	    // overwrite here as the GPR loop already ran.
206	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
207	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
208	
209	    clear_cmderr_if_set();
210	    request_resume();
211	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
212	                   "ResumeDriver resume");
213	  }
214	
215	private:
216	  void request_halt()
217	  {
218	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
219	  }
220	
221	  void request_resume()
222	  {
223	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
224	  }
225	
226	  void write_64bit_register(uint16_t regno, uint64_t value)
227	  {
228	    write_register_abstract(bus_, regno, value);
229	  }
230	
231	  // Abstract-first CSR write with Program Buffer fallback.
232	  // Tries an abstract register write; if the DM signals cmderr, clears it,
233	  // stages the value in scratch_gpr via abstract GPR write, then executes a
234	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
235	  // to x5 (t0) which the GPR restore loop overwrites later.
236	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
237	                                 uint8_t scratch_gpr = 5)
238	  {
239	    write_64bit_register(regno_csr(csr), value);
240	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
241	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
242	    write_64bit_register(regno_gpr(scratch_gpr), value);
243	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
244	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
245	  }
246	
247	  // Write a CSR-addressable register and clear any cmderr the DM raised.
248	  // Used for CSRs whose abstract-access support may be implementation
249	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
250	  // remaining writes.
251	  void write_csr_tolerant(uint16_t csr, uint64_t value)
252	  {
253	    write_64bit_register(regno_csr(csr), value);
254	    clear_cmderr_if_set();
255	  }
256	
257	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
258	  // is rejected until the bits are W1C-cleared. We tolerate per-register
259	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
260	  // error before resuming so the hart isn't left in a stuck state.
261	  // B17: record the last observed non-zero cmderr and a clear count so a
262	  // partially-broken restore is observable via the public accessors
263	  // instead of silently swallowed.
264	  void clear_cmderr_if_set()
265	  {
266	    const auto status = bus_.read(kAbstractcs);
267	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
268	    if (code != 0u) {
269	      last_observed_cmderr_ = code;
270	      ++cmderr_clear_count_;
271	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
272	    }
273	  }
274	
275	  DmiBus& bus_;
276	  uint32_t last_observed_cmderr_ = 0;
277	  uint64_t cmderr_clear_count_   = 0;
278	
279	public:
280	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
281	  // at least one abstract write tripped a sticky cmderr the restore
282	  // tolerated by clearing. cmderr_clear_count() is the total number of
283	  // such clears across all calls into clear_cmderr_if_set() this run.
284	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
285	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
286	};
287	
288	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
289	// via an Abstract Command. Halts-and-reads contract: caller must have the
290	// hart in the halted state. Shared by StateDrain (drain at exit), and by
291	// MeasureStartSnapshot (snapshot at K-th retire). If abstractcs.cmderr
292	// goes sticky after the command, the helper clears it and reports 0
293	// rather than blocking the caller -- a missing CSR mirrors as zero
294	// instead of corrupting the adjacent field.
295	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
296	                                     const char* poll_label
297	                                       = "read_register_64")
298	  -> std::optional<uint64_t>
299	{
300	  using RD = ResumeDriver;
301	  bus.write(RD::kCommand,
302	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
303	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
304	  const auto status = bus.read(RD::kAbstractcs);
305	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
306	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
307	    return std::nullopt;
308	  }
309	  const uint64_t lo = bus.read(RD::kData0);
310	  const uint64_t hi = bus.read(RD::kData1);
311	  return lo | (hi << 32);
312	}
313	
314	inline auto read_register_64(DmiBus& bus, uint16_t regno,
315	                             const char* poll_label = "read_register_64")
316	  -> uint64_t
317	{
318	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
319	}
320	
321	}  // namespace hybrid
