29	typedef struct {
30	    struct qemu_plugin_register *gpr[32];
31	    struct qemu_plugin_register *fpr[32];
32	    struct qemu_plugin_register *fcsr;  // L20: frm[7:5] | fflags[4:0]
33	    struct qemu_plugin_register *pc;
34	    struct qemu_plugin_register *priv;  // L6: gdbstub virtual feature
35	
36	    // M-mode CSRs as exposed by QEMU's gdbstub csr feature.
37	    struct qemu_plugin_register *mstatus;
38	    struct qemu_plugin_register *mepc;
39	    struct qemu_plugin_register *mtvec;
40	    struct qemu_plugin_register *mcause;
41	    struct qemu_plugin_register *mtval;
42	    struct qemu_plugin_register *mscratch;
43	    struct qemu_plugin_register *medeleg;
44	    struct qemu_plugin_register *mideleg;
45	    struct qemu_plugin_register *mip;
46	    struct qemu_plugin_register *mie;
47	    struct qemu_plugin_register *mcycle;
48	    struct qemu_plugin_register *minstret;
49	    struct qemu_plugin_register *satp;
50	
51	    struct qemu_plugin_register *pmpcfg[HYBRID_PMP_CFG_NUM];
52	    struct qemu_plugin_register *pmpaddr[HYBRID_PMP_ADDR_NUM];
53	
54	    struct qemu_plugin_register *vstart;
55	    struct qemu_plugin_register *vxsat;
56	    struct qemu_plugin_register *vxrm;
57	    struct qemu_plugin_register *vcsr;
58	    struct qemu_plugin_register *vtype;
59	    struct qemu_plugin_register *vl;
60	    struct qemu_plugin_register *vlenb;
61	    struct qemu_plugin_register *vreg[32];
62	
63	    // icount-trigger mode: per-vcpu retired-insn counter, incremented in
64	    // on_icount_tick. When icount_target is reached, the same drain path
65	    // as CSR/PC mode fires (on_handoff -> write_state_atomic -> exit 200).
66	    uint64_t icount_retired;
67	} VcpuRegs;
68	
69	static struct qemu_plugin_scoreboard *vcpu_state;
70	static char *outfile_path;
71	
72	// PC-trigger mode: when enter_pc_arg is non-zero (set via plugin arg
73	// `enter_pc=0x...`), the CSR-insn matcher is bypassed entirely and the
74	// drain callback is registered only for instructions whose vaddr equals
75	// enter_pc_arg. The kind reported on the drain is HYBRID_HANDOFF_ENTER
76	// (entry into vsim), matching marker-mode enter-marker semantics.
77	static uint64_t enter_pc_arg;
78	static int pc_mode;
79	
80	// icount-trigger mode: when icount_target is non-zero (set via plugin arg
81	// `icount=N`), every translated insn gets an exec callback that bumps a
82	// per-vcpu counter; on threshold-cross the drain fires at that insn
83	// boundary. Coexists with CSR/PC modes - either trigger can win.
84	static uint64_t icount_target;
85	static int icount_mode;
86	
87	// BBV-emit mode (SimPoint profile): when bbv_mode is set (plugin args
88	// `bbv_out=PATH,slice=N`), every translated insn gets an exec callback
89	// that ticks a global BBV counter; one .bb row per N retired insns is
90	// flushed to PATH. Coexists with the drain triggers - independently
91	// registered before icount so that on co-firing (icount target == slice
92	// multiple) the slice row is emitted before exit(200).
93	static BbvEmit *bbv_emit;
94	static char    *bbv_out_path;
95	static uint64_t bbv_slice_target;
96	static int      bbv_mode;
97	
98	// Slice-consume mode (SimPoint replay; F11): when slice_consume_mode is
99	// set (plugin args `slice=N,slice_at=K`), the plugin counts slice
100	// boundaries (one boundary per N retired insns) and drains at the end
101	// of slice index K (0-based). With K=2 and slice=1000, drain fires at
102	// insn 3000 - the boundary that closes the third slice. The orchestrator
103	// chains one invocation per SimPoint cluster-representative slice idx.
104	// Shares the `slice=` parameter with BBV-emit; works independently of
105	// whether `bbv_out=` is also set.
106	static uint64_t slice_at_target;
107	static int      slice_consume_mode;
108	static uint64_t slice_consume_acc;
109	static uint64_t slice_consume_idx;
110	
111	// Drain-at-exit mode (F14): when drain_at_exit_mode is set (plugin arg
112	// `drain_at_exit=1`), the plugin registers a per-insn exec callback that
113	// bumps `atexit_insn_count`, and a `qemu_plugin_register_atexit_cb` that
114	// drains state on natural program exit (e.g. semihosting EXIT). The
115	// atexit callback overrides s.minstret with the plugin counter so the
116	// caller (./hsim estimate --icount 0) gets a true retired-insn count
117	// independent of QEMU's PMU semantics (which can return host ticks on
118	// system-mode without `-icount`). `drained_already` suppresses the
119	// atexit path if any other trigger (CSR/PC/icount/slice) drained first.
120	static int      drain_at_exit_mode;
121	static volatile int drained_already;
122	static uint64_t atexit_insn_count;
123	
124	// Oracle exit-drain mode (verify_oracle F1): when exit_marker_mode or
125	// exit_pc_mode is set (plugin args `exit_marker=1` / `exit_pc=0x...`), a
126	// pure-QEMU run produces the differential verifier's reference state. Every
127	// insn gets an exec callback (icount-mode cost class): the tick ARMS on the
128	// ROI exit boundary (EXIT marker match, or vaddr == exit_pc) and DRAINS on
129	// the next callback. Exec callbacks fire before their insn executes, so the
130	// armed drain captures "after the boundary insn retired" -- exactly vsim's
131	// exit-drain record (DPC = next insn to execute) -- and reports that next
132	// insn's vaddr as pc, correct even when the boundary insn branches.
133	// Exclusive with the other trigger modes: the oracle run never hands off.
134	//
135	// drain_pc=0x... (optional modifier): drain at the first post-arm tick whose
136	// vaddr equals drain_pc, instead of the very next tick. The differential
137	// harness passes vsim's actual drained pc here: vsim's DMI halt lands a
138	// variable 0-3 insns past the trigger (the core keeps retiring while the
139	// haltreq propagates), and the two states only compare equal when both
140	// sides sample the SAME architectural point. If vsim's pc is never reached
141	// (a real control-flow divergence), the oracle never drains and QEMU runs
142	// to completion -- the caller sees exit != 200.
143	static uint64_t exit_pc_arg;
144	static int      exit_pc_mode;
145	static int      exit_marker_mode;
146	static uint64_t drain_pc_arg;
147	static int      drain_pc_set;
148	static volatile int oracle_armed;
149	
150	// Cosim oracle mode (cosim_roi F3): when cosim_marker_mode or cosim_pc_mode
151	// is set (plugin args `cosim_marker=1` / `cosim_pc=0x...`), a per-insn exec
152	// callback ARMS at the ROI entry boundary, then drains hybrid_state_v1 at
153	// the post-entry retire counts listed in cosim_counts=a:b:c (strictly
154	// ascending). Every count but the last writes <outfile>.ckpt<k> (k from 1)
155	// and execution continues; the LAST drains <outfile> and exits 200. The
156	// counts come from the vsim leg's checkpoint minstret deltas, so both
157	// engines sample the SAME architectural points (see cosim_roi.md).
158	//
159	// Counting mirrors the vsim leg's minstret reference point:
160	//   marker mode: the ENTER marker is counted by NEITHER side (QEMU1 drains
161	//     pre-marker, vsim resumes past it) -- the arming tick does not count.
162	//   pc mode: the boundary insn retires INSIDE the window (the pc-mode
163	//     handoff resumes AT the boundary), so the arming tick counts it.
164	// Exclusive with every other trigger mode (including the exit oracle).
165	static uint64_t *cosim_counts;
166	static size_t    cosim_n_counts;
167	static uint64_t  cosim_pc_arg;
168	static int       cosim_pc_mode;
169	static int       cosim_marker_mode;
170	static volatile int cosim_armed;
171	static uint64_t  cosim_done;   // post-entry retires so far
172	static size_t    cosim_idx;    // next cosim_counts[] target
173	
174	// Lock-step oracle mode (cosim_redesign F5): `lockstep_pc=0x...` arms at
175	// the given vaddr, then drains the full state BEFORE every execution
176	// attempt, appending each record to the `outfile` stream (outfile IS the
177	// stream in this mode; there is no separate final state file). Exec
178	// callbacks fire pre-execution, so record k = state before attempt k+1 --
179	// the exact point where vsim's dcsr.step halt lands, traps included (a
180	// trapped attempt's next callback is the handler entry on both sides).
181	// Stops at `lockstep_max=K` records (exit 200) or at natural program exit.
182	static uint64_t  lockstep_pc_arg;
183	static int       lockstep_pc_mode;
184	static uint64_t  lockstep_max;
185	static volatile int lockstep_armed;
186	static uint64_t  lockstep_count;
