188	static struct qemu_plugin_register *find_reg(GArray *regs, const char *name)
189	{
190	    for (guint i = 0; i < regs->len; i++) {
191	        qemu_plugin_reg_descriptor *rd =
192	            &g_array_index(regs, qemu_plugin_reg_descriptor, i);
193	        if (g_ascii_strcasecmp(rd->name, name) == 0) {
194	            return rd->handle;
195	        }
196	    }
197	    return NULL;
198	}
