200	// Lazily resolves register handles. The plugin's vcpu_init runs before
201	// QEMU has registered the dynamic gdb coprocessors (FPU, virtual, csr,
202	// vector), so qemu_plugin_get_registers() returns only the 33 core CPU
203	// regs at that moment. By the time the entry trigger fires, all dynamic
204	// features are registered and a fresh call returns the full list.
205	static void resolve_handles(VcpuRegs *v)
206	{
207	    g_autoptr(GArray) regs = qemu_plugin_get_registers();
208	    for (int i = 0; i < 32; i++) {
209	        v->gpr[i] = find_reg(regs, hybrid_gpr_names[i]);
210	        v->fpr[i] = find_reg(regs, hybrid_fpr_names[i]);
211	    }
212	    v->fcsr = find_reg(regs, "fcsr");
213	    v->pc = find_reg(regs, "pc");
214	    v->priv = find_reg(regs, "priv");
215	
216	    v->mstatus  = find_reg(regs, "mstatus");
217	    v->mepc     = find_reg(regs, "mepc");
218	    v->mtvec    = find_reg(regs, "mtvec");
219	    v->mcause   = find_reg(regs, "mcause");
220	    v->mtval    = find_reg(regs, "mtval");
221	    v->mscratch = find_reg(regs, "mscratch");
222	    v->medeleg  = find_reg(regs, "medeleg");
223	    v->mideleg  = find_reg(regs, "mideleg");
224	    v->mip      = find_reg(regs, "mip");
225	    v->mie      = find_reg(regs, "mie");
226	    v->mcycle   = find_reg(regs, "mcycle");
227	    v->minstret = find_reg(regs, "minstret");
228	    v->satp     = find_reg(regs, "satp");
229	
230	    char buf[16];
231	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++) {
232	        g_snprintf(buf, sizeof(buf), "pmpcfg%d", i);
233	        v->pmpcfg[i] = find_reg(regs, buf);
234	    }
235	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++) {
236	        g_snprintf(buf, sizeof(buf), "pmpaddr%d", i);
237	        v->pmpaddr[i] = find_reg(regs, buf);
238	    }
239	
240	    v->vstart = find_reg(regs, "vstart");
241	    v->vxsat  = find_reg(regs, "vxsat");
242	    v->vxrm   = find_reg(regs, "vxrm");
243	    v->vcsr   = find_reg(regs, "vcsr");
244	    v->vtype  = find_reg(regs, "vtype");
245	    v->vl     = find_reg(regs, "vl");
246	    v->vlenb  = find_reg(regs, "vlenb");
247	    for (int i = 0; i < 32; i++) {
248	        g_snprintf(buf, sizeof(buf), "v%d", i);
249	        v->vreg[i] = find_reg(regs, buf);
250	    }
251	}
252	
253	static uint64_t read_reg64(struct qemu_plugin_register *h)
254	{
255	    if (!h) return 0;
256	    g_autoptr(GByteArray) buf = g_byte_array_new();
257	    int sz = qemu_plugin_read_register(h, buf);
258	    if (sz <= 0) return 0;
259	    uint64_t v = 0;
260	    memcpy(&v, buf->data, sz < 8 ? (size_t) sz : 8);
261	    return v;
262	}
263	
264	// Reads up to `dst_max` bytes from a register handle. Returns the byte
265	// count written (0 on failure or NULL handle). Used for vector regs whose
266	// width = vlenb bytes.
267	static size_t read_reg_bytes(struct qemu_plugin_register *h,
268	                             uint8_t *dst, size_t dst_max)
269	{
270	    if (!h || dst_max == 0) return 0;
271	    g_autoptr(GByteArray) buf = g_byte_array_new();
272	    int sz = qemu_plugin_read_register(h, buf);
273	    if (sz <= 0) return 0;
274	    size_t n = (size_t) sz < dst_max ? (size_t) sz : dst_max;
275	    memcpy(dst, buf->data, n);
276	    return n;
277	}
278	
279	// Atomic on POSIX: write to a mkstemp-reserved tmp file, fsync, rename.
280	// mkstemp guarantees uniqueness via a 6-char random suffix + atomic
281	// O_EXCL-style inode reservation, so concurrent plugin instances cannot
282	// collide even under aggressive PID reuse (B13). The tmp lives in the
283	// same directory as `path` so the rename is intra-filesystem.
284	static int write_state_atomic(const struct hybrid_state_v1 *s, const char *path)
285	{
286	    char tmp[PATH_MAX];
287	    int n = g_snprintf(tmp, sizeof(tmp), "%s.tmp.XXXXXX", path);
288	    if (n < 0 || (size_t) n >= sizeof(tmp)) {
289	        fprintf(stderr, "hybrid_handoff: tmp path too long\n");
290	        return -1;
291	    }
292	    int fd = g_mkstemp(tmp);
293	    if (fd < 0) {
294	        perror("hybrid_handoff: g_mkstemp");
295	        return -1;
296	    }
297	    // g_mkstemp creates the file 0600; no further chmod needed.
298	    ssize_t want = (ssize_t) sizeof(*s);
299	    ssize_t got = write(fd, s, sizeof(*s));
300	    if (got != want) {
301	        perror("hybrid_handoff: write");
302	        close(fd);
303	        unlink(tmp);
304	        return -1;
305	    }
306	    fsync(fd);
307	    close(fd);
308	    if (rename(tmp, path) != 0) {
309	        perror("hybrid_handoff: rename");
310	        unlink(tmp);
311	        return -1;
312	    }
313	    return 0;
314	}
315	
316	// Append one record to a `.ckpts` stream (concatenated hybrid_state_v1,
317	// cosim_redesign F3). No tmp-rename dance: the stream has a single writer
318	// and readers only run after the producer exits.
319	static int append_state_stream(const struct hybrid_state_v1 *s,
320	                               const char *path)
321	{
322	    FILE *f = fopen(path, "ab");
323	    if (!f) {
324	        perror("hybrid_handoff: fopen stream");
325	        return -1;
326	    }
327	    const size_t n = fwrite(s, 1, sizeof(*s), f);
328	    fclose(f);
329	    return n == sizeof(*s) ? 0 : -1;
330	}
331	
332	// Drain CPU state into `*s`. pc is computed by the caller (from a
333	// HandoffSite for trigger paths, or 0 for the atexit path which lacks an
334	// insn context). If minstret_override is non-zero, it replaces QEMU's PMU
335	// minstret (used by drain_at_exit mode to record a plugin-counted
336	// retired-insn total).
337	static void drain_state_into(unsigned int vcpu_idx, uint64_t pc,
338	                             uint64_t minstret_override,
339	                             struct hybrid_state_v1 *sp)
340	{
341	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
342	    resolve_handles(v);
343	    memset(sp, 0, sizeof(*sp));
344	    struct hybrid_state_v1 s = {0};
345	    s.magic   = HYBRID_STATE_MAGIC;
346	    s.version = HYBRID_STATE_VERSION;
347	    s.flags   = HYBRID_FLAG_RV64;
348	    s.hart_id = vcpu_idx;
349	    // L6: real privilege at the boundary; M-mode fallback only when the
350	    // stub doesn't advertise the gdbstub virtual feature (a missing handle
351	    // reads as 0 = U, which would silently demote the hart).
352	    s.priv    = v->priv ? (read_reg64(v->priv) & 0x3) : 3;
353	    s.pc      = pc;
354	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
355	
356	    // Floating-point: only set FP flag if at least one handle was bound,
357	    // i.e. QEMU advertised the FPU feature (D extension).
358	    int has_fp = 0;
359	    for (int i = 0; i < 32; i++) {
360	        s.fpr[i] = read_reg64(v->fpr[i]);
361	        if (v->fpr[i]) has_fp = 1;
362	    }
363	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
364	    s.fcsr = read_reg64(v->fcsr);  // L20: rides HYBRID_FLAG_FP
365	
366	    s.mstatus  = read_reg64(v->mstatus);
367	    s.mepc     = read_reg64(v->mepc);
368	    s.mtvec    = read_reg64(v->mtvec);
369	    s.mcause   = read_reg64(v->mcause);
370	    s.mtval    = read_reg64(v->mtval);
371	    s.mscratch = read_reg64(v->mscratch);
372	    s.medeleg  = read_reg64(v->medeleg);
373	    s.mideleg  = read_reg64(v->mideleg);
374	    s.mip      = read_reg64(v->mip);
375	    s.mie      = read_reg64(v->mie);
376	    s.mcycle   = read_reg64(v->mcycle);
377	    s.minstret = minstret_override ? minstret_override
378	                                   : read_reg64(v->minstret);
379	    s.satp     = read_reg64(v->satp);
380	
381	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
382	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
383	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
384	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
385	
386	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
387	    // bounds the per-register byte count copied into vreg[]. The policy
388	    // helper (hybrid_v_drain_policy) decides SKIP/OK/ABORT from the
389	    // handle truthiness so we don't conflate "stub missing vlenb" with
390	    // "V disabled at runtime"; see include/hybrid/v_drain_policy.h.
391	    s.vstart = read_reg64(v->vstart);
392	    s.vxsat  = read_reg64(v->vxsat);
393	    s.vxrm   = read_reg64(v->vxrm);
394	    s.vcsr   = read_reg64(v->vcsr);
395	    s.vtype  = read_reg64(v->vtype);
396	    s.vl     = read_reg64(v->vl);
397	    s.vlenb  = read_reg64(v->vlenb);
398	    int has_other_v = (v->vstart || v->vxsat || v->vxrm || v->vcsr
399	                       || v->vtype || v->vl);
400	    if (!has_other_v) {
401	        for (int i = 0; i < 32; i++)
402	            if (v->vreg[i]) { has_other_v = 1; break; }
403	    }
404	    HybridVDrainPolicy vpol = hybrid_v_drain_policy(
405	        v->vlenb != NULL, has_other_v, s.vlenb);
406	    if (vpol == HYBRID_V_DRAIN_ABORT) {
407	        if (v->vlenb == NULL)
408	            fprintf(stderr,
409	                    "hybrid_handoff: stub advertised V CSRs/regs but not "
410	                    "vlenb; refusing to drain partial V state\n");
411	        else
412	            fprintf(stderr,
413	                    "hybrid_handoff: vlenb=%" PRIu64 " exceeds the wire-format "
414	                    "ceiling HYBRID_VLEN_BYTES_MAX=%d (VLEN %d); refusing to "
415	                    "truncate V registers\n",
416	                    s.vlenb, HYBRID_VLEN_BYTES_MAX,
417	                    8 * HYBRID_VLEN_BYTES_MAX);
418	        exit(2);
419	    }
420	    if (vpol == HYBRID_V_DRAIN_OK) {
421	        s.flags |= HYBRID_FLAG_V;
422	        /* The policy guarantees vlenb <= HYBRID_VLEN_BYTES_MAX here, so the
423	         * full live register fits the wire-format slot -- no clamp (L11). */
424	        for (int i = 0; i < 32; i++)
425	            (void) read_reg_bytes(v->vreg[i],
426	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
427	                                  (size_t) s.vlenb);
428	    }
429	
430	    *sp = s;
431	}
432	
433	// Drain CPU state to `path`. Does NOT call exit -- caller decides exit(200)
434	// (normal trigger) vs _exit(200) (inside atexit chain).
435	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
436	                                uint64_t minstret_override, const char *path)
437	{
438	    struct hybrid_state_v1 s;
439	    drain_state_into(vcpu_idx, pc, minstret_override, &s);
440	    if (write_state_atomic(&s, path) != 0) {
441	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
442	        exit(2);
443	    }
444	    fprintf(stderr,
445	            "hybrid_handoff: drained state to %s (pc=%#" PRIx64 ")\n",
446	            path, s.pc);
447	}
448	
449	// Shared drain tail: capture the (pre-execution) state, report `resume_pc`
450	// as the vsim resume point, and exit 200.
451	static void handoff_drain(unsigned int vcpu_idx, uint64_t resume_pc)
452	{
453	    // F14: suppress the atexit drain path now that we have a real trigger.
454	    drained_already = 1;
455	    drain_state_to_file(vcpu_idx, resume_pc, 0, outfile_path);
456	    // 200 == kExitHandoffToQemu in verilator/src/hybrid/exit_codes.hpp.
457	    // Distinguishes drain from workload completion (0) so the orchestrator
458	    // can decide the next spawn.
459	    exit(200);
460	}
461	
462	// Marker sites. The marker is an architectural NOP, so the pre-execution
463	// state equals the post-retire state and the window resumes AFTER it
464	// (vaddr+size, computed at translation time; reading the gdbstub PC inside
465	// the exec callback can lag the actual current insn when V instructions
466	// retire just before the trigger -- TCG defers PC writes for performance).
467	static void on_handoff(unsigned int vcpu_idx, void *udata)
468	{
469	    const HandoffSite *site = (const HandoffSite *) udata;
470	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
471	    handoff_drain(vcpu_idx, compute_handoff_pc(site));
472	}
473	
474	// pc/icount/slice boundary sites. Exec callbacks fire BEFORE the insn
475	// executes, and the boundary insn is real user code (unlike a marker NOP):
476	// the drained state must resume AT the boundary so the insn executes inside
477	// the vsim window rather than on neither leg. (Skipping it corrupts the
478	// window's architectural state -- e.g. a skipped vsetivli leaves vtype.vill
479	// set and the first vector op of the window faults.)
480	static void on_handoff_boundary(unsigned int vcpu_idx, void *udata)
481	{
482	    const HandoffSite *site = (const HandoffSite *) udata;
483	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
484	    handoff_drain(vcpu_idx, site->vaddr);
485	}
486	
487	// F14: per-insn tick. Increments a global counter every retired insn so the
488	// drain-at-exit path can report a true retired-insn total (independent of
489	// QEMU's PMU semantics).
490	static void on_count_tick(unsigned int vcpu_idx, void *udata)
491	{
492	    (void) vcpu_idx;
493	    (void) udata;
494	    atexit_insn_count++;
495	}
496	
497	// F14: atexit drain. Fires when QEMU exits naturally (no ROI trigger). The
498	// record is a CONTEXT-FREE count, not an architectural drain: depending on
499	// the guest's exit path this callback runs on the vCPU thread (semihosting
500	// EXIT) or on QEMU's main loop thread (vplat/SimControl shutdown request),
501	// and on the main thread there is no vCPU context -- any
502	// qemu_plugin_read_register aborts QEMU (api.c asserts current_cpu). The
503	// only consumer (the SimPoint estimate profile) reads minstret = the
504	// plugin-side retire counter (N_total); pc=0 is the positive marker that
505	// the atexit path drained (no trigger). If any other trigger already
506	// drained, return immediately (drained_already guards against double
507	// drain). Inside an atexit handler, exit() is UB per C11 7.22.4.4; use
508	// _exit() to skip the rest of the atexit chain.
509	static void on_atexit(qemu_plugin_id_t id, void *udata)
510	{
511	    (void) id;
512	    (void) udata;
513	    if (drained_already) return;
514	    if (!drain_at_exit_mode) return;
515	    struct hybrid_state_v1 s = {0};
516	    s.magic    = HYBRID_STATE_MAGIC;
517	    s.version  = HYBRID_STATE_VERSION;
518	    s.flags    = HYBRID_FLAG_RV64;
519	    s.priv     = 3;
520	    s.minstret = atexit_insn_count;
521	    if (write_state_atomic(&s, outfile_path) != 0)
522	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
523	    else
524	        fprintf(stderr,
525	                "hybrid_handoff: drained exit count record to %s "
526	                "(minstret=%" PRIu64 ")\n",
527	                outfile_path, s.minstret);
528	    fflush(stderr);
529	    _exit(200);
530	}
531	
532	// Per-insn tick for oracle exit-drain mode. udata is this insn's HandoffSite.
533	// When armed (the exit boundary's own tick ran), this tick fires before its
534	// insn executes, so a drain here records the post-retire state of the
535	// boundary insn with pc = the dynamically-next insn's vaddr.
536	static void on_oracle_tick(unsigned int vcpu_idx, void *udata)
537	{
538	    const HandoffSite *site = (const HandoffSite *) udata;
539	    if (oracle_armed
540	        && (!drain_pc_set || site->vaddr == drain_pc_arg)) {
541	        handoff_drain(vcpu_idx, site->vaddr);
542	    }
543	    if (exit_pc_mode ? (site->vaddr == exit_pc_arg)
544	                     : (site->kind == HYBRID_HANDOFF_EXIT)) {
545	        oracle_armed = 1;
546	    }
547	}
548	
549	// Checkpoint drain for cosim mode: append to the <outfile>.ckpts stream and
550	// KEEP RUNNING (no exit, drained_already untouched -- the final count uses
551	// handoff_drain).
552	static void cosim_checkpoint_drain(unsigned int vcpu_idx, uint64_t pc,
553	                                   size_t k)
554	{
555	    g_autofree char *path = g_strdup_printf("%s.ckpts", outfile_path);
556	    struct hybrid_state_v1 s;
557	    drain_state_into(vcpu_idx, pc, 0, &s);
558	    if (append_state_stream(&s, path) != 0) {
559	        fprintf(stderr, "hybrid_handoff: failed to append checkpoint %zu\n",
560	                k);
561	        exit(2);
562	    }
563	    fprintf(stderr,
564	            "hybrid_handoff: checkpoint %zu appended to %s (pc=%#" PRIx64
565	            ")\n", k, path, s.pc);
566	}
567	
568	// Per-insn tick for cosim mode. udata is this insn's HandoffSite. Exec
569	// callbacks fire pre-execution: at an armed tick, `cosim_done` post-entry
570	// insns have retired and the current insn has not, so draining when
571	// cosim_done == target captures "entry + target retires" with pc = the
572	// dynamically-next insn's vaddr -- the same point as the vsim checkpoint's
573	// DPC at minstret delta == target.
574	static void on_cosim_tick(unsigned int vcpu_idx, void *udata)
575	{
576	    const HandoffSite *site = (const HandoffSite *) udata;
577	    if (!cosim_armed) {
578	        if (cosim_pc_mode ? (site->vaddr == cosim_pc_arg)
579	                          : (site->kind == HYBRID_HANDOFF_ENTER)) {
580	            cosim_armed = 1;
581	            // Marker mode: the marker is counted by neither side -- done.
582	            // pc mode: the boundary insn retires inside the window (the
583	            // handoff resumes AT it) -- fall through and count this tick.
584	            if (!cosim_pc_mode) return;
585	        } else {
586	            return;
587	        }
588	    }
589	    if (cosim_idx < cosim_n_counts && cosim_done == cosim_counts[cosim_idx]) {
590	        if (cosim_idx + 1 == cosim_n_counts)
591	            handoff_drain(vcpu_idx, site->vaddr);  // final: exits 200
592	        else
593	            cosim_checkpoint_drain(vcpu_idx, site->vaddr, cosim_idx + 1);
594	        cosim_idx++;
595	    }
596	    cosim_done++;
597	}
598	
599	// Per-insn tick for lock-step oracle mode. udata is this insn's
600	// HandoffSite. Drains BEFORE the insn executes (record k = state before
601	// attempt k+1) and appends to the outfile stream.
602	static void on_lockstep_tick(unsigned int vcpu_idx, void *udata)
603	{
604	    const HandoffSite *site = (const HandoffSite *) udata;
605	    if (!lockstep_armed) {
606	        if (site->vaddr != lockstep_pc_arg) return;
607	        lockstep_armed = 1;
608	    }
609	    struct hybrid_state_v1 s;
610	    drain_state_into(vcpu_idx, site->vaddr, 0, &s);
611	    if (append_state_stream(&s, outfile_path) != 0) {
612	        fprintf(stderr, "hybrid_handoff: failed to append lockstep record "
613	                "%" PRIu64 "\n", lockstep_count);
614	        exit(2);
615	    }
616	    lockstep_count++;
617	    if (lockstep_max != 0 && lockstep_count >= lockstep_max) {
618	        drained_already = 1;
619	        fprintf(stderr,
620	                "hybrid_handoff: lockstep done, %" PRIu64 " record(s) in "
621	                "%s\n", lockstep_count, outfile_path);
622	        fflush(stderr);
623	        exit(200);
624	    }
625	}
626	
627	// Per-insn tick for icount mode. udata is the per-insn HandoffSite
628	// pre-allocated at translation time, so on_handoff's compute_handoff_pc
629	// returns the lag-free post-trigger PC (same property as the CSR path).
630	static void on_icount_tick(unsigned int vcpu_idx, void *udata)
631	{
632	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
633	    if (++v->icount_retired < icount_target) return;
634	    on_handoff_boundary(vcpu_idx, udata);
635	}
636	
637	// Per-insn tick for BBV-emit mode. udata is the bb_id (1-based) cast to
638	// pointer; that mapping is stable across calls because bbv_emit_assign_id
639	// is hashed by TB-start PC. The tick attributes one insn to the bb_id and
640	// flushes a slice row when the per-slice counter saturates.
641	static void on_bbv_tick(unsigned int vcpu_idx, void *udata)
642	{
643	    (void) vcpu_idx;
644	    uint64_t bb_id = (uint64_t) GPOINTER_TO_UINT(udata);
645	    bbv_emit_tick(bbv_emit, bb_id);
646	}
647	
648	// Per-insn tick for slice-consume mode (F11). Counts insns into the
649	// slice accumulator; on each slice boundary increments slice_consume_idx
650	// and resets the accumulator. Once slice_consume_idx exceeds the target
651	// slice index, drains via on_handoff at that same insn boundary. udata
652	// is the per-insn HandoffSite (allocated at translation time) so the
653	// post-trigger PC reaches on_handoff lag-free.
654	static void on_slice_consume_tick(unsigned int vcpu_idx, void *udata)
655	{
656	    if (++slice_consume_acc < bbv_slice_target) return;
657	    slice_consume_acc = 0;
658	    if (slice_consume_idx++ < slice_at_target) return;
659	    // After the post-increment above, slice_consume_idx == slice_at_target+1
660	    // (the count of fully retired slices). Log so the e2e test can verify
661	    // drain timing without relying on minstret (which is a cycle-counter
662	    // proxy on andes-ax45mpv and does not track plugin-counted insns).
663	    fprintf(stderr,
664	            "hybrid_handoff: slice-consume drain (idx=%" PRIu64
665	            " target=%" PRIu64 ")\n",
666	            slice_consume_idx, slice_at_target);
667	    on_handoff_boundary(vcpu_idx, udata);
668	}
669	
670	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
671	{
672	    (void) id;
673	    size_t n = qemu_plugin_tb_n_insns(tb);
674	
675	    // BBV-mode: assign a stable bb_id to this TB (1-based, hashed by
676	    // TB-start vaddr). Same id is shared by every insn in the TB.
677	    uint64_t bb_id = 0;
678	    if (bbv_mode && n > 0) {
679	        uint64_t tb_pc = qemu_plugin_insn_vaddr(qemu_plugin_tb_get_insn(tb, 0));
680	        bb_id = bbv_emit_assign_id(bbv_emit, tb_pc);
681	    }
682	
683	    for (size_t i = 0; i < n; i++) {
684	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
685	
686	        // Oracle exit-drain mode: exclusive with every other mode (enforced
687	        // at install), so it owns the insn's registration outright. The site
688	        // carries the marker kind so the tick can arm on the EXIT marker.
689	        if (exit_marker_mode || exit_pc_mode) {
690	            HandoffSite *site = g_new0(HandoffSite, 1);
691	            site->kind  = HYBRID_HANDOFF_NONE;
692	            site->vaddr = qemu_plugin_insn_vaddr(insn);
693	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
694	            if (exit_marker_mode && site->size == 4) {
695	                uint32_t raw = 0;
696	                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
697	                    hybrid_match_handoff_insn(raw, &site->kind);
698	            }
699	            qemu_plugin_register_vcpu_insn_exec_cb(
700	                insn, on_oracle_tick, QEMU_PLUGIN_CB_R_REGS, site);
701	            continue;
702	        }
703	
704	        // Cosim oracle mode: exclusive with every other mode (enforced at
705	        // install). Same site shape as the exit oracle; kind carries the
706	        // marker match so the tick can arm on the ENTER marker.
707	        if (cosim_marker_mode || cosim_pc_mode) {
708	            HandoffSite *site = g_new0(HandoffSite, 1);
709	            site->kind  = HYBRID_HANDOFF_NONE;
710	            site->vaddr = qemu_plugin_insn_vaddr(insn);
711	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
712	            if (cosim_marker_mode && site->size == 4) {
713	                uint32_t raw = 0;
714	                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
715	                    hybrid_match_handoff_insn(raw, &site->kind);
716	            }
717	            qemu_plugin_register_vcpu_insn_exec_cb(
718	                insn, on_cosim_tick, QEMU_PLUGIN_CB_R_REGS, site);
719	            continue;
720	        }
721	
722	        // Lock-step oracle mode: exclusive with every other mode (enforced
723	        // at install). Every insn ticks; the tick arms at lockstep_pc.
724	        if (lockstep_pc_mode) {
725	            HandoffSite *site = g_new0(HandoffSite, 1);
726	            site->kind  = HYBRID_HANDOFF_NONE;
727	            site->vaddr = qemu_plugin_insn_vaddr(insn);
728	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
729	            qemu_plugin_register_vcpu_insn_exec_cb(
730	                insn, on_lockstep_tick, QEMU_PLUGIN_CB_R_REGS, site);
731	            continue;
732	        }
733	
734	        // F14 count tick: registered FIRST so the count is incremented
735	        // before any trigger callback can call exit(200). NO_REGS keeps
736	        // the per-insn cost minimal (a single uint64 add).
737	        if (drain_at_exit_mode) {
738	            qemu_plugin_register_vcpu_insn_exec_cb(
739	                insn, on_count_tick, QEMU_PLUGIN_CB_NO_REGS, NULL);
740	        }
741	
742	        // BBV callback is registered BEFORE icount so that if both modes
743	        // fire on the same insn (icount target == slice multiple), the
744	        // slice row is emitted before exit(200) is called.
745	        if (bbv_mode) {
746	            qemu_plugin_register_vcpu_insn_exec_cb(
747	                insn, on_bbv_tick, QEMU_PLUGIN_CB_NO_REGS,
748	                GUINT_TO_POINTER((guint) bb_id));
749	        }
750	
751	        // Slice-consume callback (F11). Registered after BBV so a BBV
752	        // row at the same boundary is flushed first; ordering vs icount
753	        // is irrelevant (both drain).
754	        if (slice_consume_mode) {
755	            HandoffSite *site = g_new0(HandoffSite, 1);
756	            site->kind  = HYBRID_HANDOFF_ENTER;
757	            site->vaddr = qemu_plugin_insn_vaddr(insn);
758	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
759	            qemu_plugin_register_vcpu_insn_exec_cb(
760	                insn, on_slice_consume_tick, QEMU_PLUGIN_CB_R_REGS, site);
761	        }
762	
763	        if (icount_mode) {
764	            HandoffSite *site = g_new0(HandoffSite, 1);
765	            site->kind  = HYBRID_HANDOFF_ENTER;
766	            site->vaddr = qemu_plugin_insn_vaddr(insn);
767	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
768	            qemu_plugin_register_vcpu_insn_exec_cb(
769	                insn, on_icount_tick, QEMU_PLUGIN_CB_R_REGS, site);
770	        }
771	
772	        if (pc_mode) {
773	            // PC-trigger mode: vaddr-only match; the drain resumes AT the
774	            // boundary (on_handoff_boundary), so the insn size is recorded
775	            // only for completeness.
776	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
777	            HandoffSite *site = g_new0(HandoffSite, 1);
778	            site->kind  = HYBRID_HANDOFF_ENTER;
779	            site->vaddr = qemu_plugin_insn_vaddr(insn);
780	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
781	            qemu_plugin_register_vcpu_insn_exec_cb(
782	                insn, on_handoff_boundary, QEMU_PLUGIN_CB_R_REGS, site);
783	            continue;
784	        }
785	
786	        // Marker-trigger mode (default).
787	        // The markers are `slti x0, x0, 0x5A0/0x5A1`, always 32-bit
788	        // (sz==4): SLTI has no compressed form, so the sz!=4 skip is
789	        // exact, not an approximation.
790	        size_t sz = qemu_plugin_insn_size(insn);
791	        if (sz != 4) continue;
792	        uint32_t raw = 0;
793	        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
794	            continue;
795	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
796	        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
797	        HandoffSite *site = g_new0(HandoffSite, 1);
798	        site->kind  = kind;
799	        site->vaddr = qemu_plugin_insn_vaddr(insn);
800	        site->size  = (uint32_t) sz;
801	        qemu_plugin_register_vcpu_insn_exec_cb(
802	            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
803	    }
804	}
