806	QEMU_PLUGIN_EXPORT int qemu_plugin_install(qemu_plugin_id_t id,
807	                                           const qemu_info_t *info,
808	                                           int argc, char **argv)
809	{
810	    (void) info;
811	    for (int i = 0; i < argc; i++) {
812	        g_auto(GStrv) tok = g_strsplit(argv[i], "=", 2);
813	        if (g_strcmp0(tok[0], "outfile") == 0 && tok[1]) {
814	            outfile_path = g_strdup(tok[1]);
815	        } else if (g_strcmp0(tok[0], "enter_pc") == 0 && tok[1]) {
816	            char *endp = NULL;
817	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
818	            if (!endp || *endp != '\0') {
819	                fprintf(stderr, "hybrid_handoff: invalid enter_pc=%s\n",
820	                        tok[1]);
821	                return -1;
822	            }
823	            enter_pc_arg = (uint64_t) v;
824	            pc_mode = 1;
825	        } else if (g_strcmp0(tok[0], "icount") == 0 && tok[1]) {
826	            char *endp = NULL;
827	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
828	            if (!endp || *endp != '\0' || v == 0) {
829	                fprintf(stderr, "hybrid_handoff: invalid icount=%s\n",
830	                        tok[1]);
831	                return -1;
832	            }
833	            icount_target = (uint64_t) v;
834	            icount_mode = 1;
835	        } else if (g_strcmp0(tok[0], "bbv_out") == 0 && tok[1]) {
836	            bbv_out_path = g_strdup(tok[1]);
837	            bbv_mode = 1;
838	        } else if (g_strcmp0(tok[0], "slice") == 0 && tok[1]) {
839	            char *endp = NULL;
840	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
841	            if (!endp || *endp != '\0' || v == 0) {
842	                fprintf(stderr, "hybrid_handoff: invalid slice=%s\n",
843	                        tok[1]);
844	                return -1;
845	            }
846	            bbv_slice_target = (uint64_t) v;
847	        } else if (g_strcmp0(tok[0], "slice_at") == 0 && tok[1]) {
848	            char *endp = NULL;
849	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
850	            if (!endp || *endp != '\0') {
851	                fprintf(stderr, "hybrid_handoff: invalid slice_at=%s\n",
852	                        tok[1]);
853	                return -1;
854	            }
855	            slice_at_target = (uint64_t) v;
856	            slice_consume_mode = 1;
857	        } else if (g_strcmp0(tok[0], "exit_pc") == 0 && tok[1]) {
858	            char *endp = NULL;
859	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
860	            if (!endp || *endp != '\0') {
861	                fprintf(stderr, "hybrid_handoff: invalid exit_pc=%s\n",
862	                        tok[1]);
863	                return -1;
864	            }
865	            exit_pc_arg = (uint64_t) v;
866	            exit_pc_mode = 1;
867	        } else if (g_strcmp0(tok[0], "exit_marker") == 0 && tok[1]) {
868	            char *endp = NULL;
869	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
870	            if (!endp || *endp != '\0') {
871	                fprintf(stderr, "hybrid_handoff: invalid exit_marker=%s\n",
872	                        tok[1]);
873	                return -1;
874	            }
875	            exit_marker_mode = (v != 0);
876	        } else if (g_strcmp0(tok[0], "drain_pc") == 0 && tok[1]) {
877	            char *endp = NULL;
878	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
879	            if (!endp || *endp != '\0') {
880	                fprintf(stderr, "hybrid_handoff: invalid drain_pc=%s\n",
881	                        tok[1]);
882	                return -1;
883	            }
884	            drain_pc_arg = (uint64_t) v;
885	            drain_pc_set = 1;
886	        } else if (g_strcmp0(tok[0], "cosim_pc") == 0 && tok[1]) {
887	            char *endp = NULL;
888	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
889	            if (!endp || *endp != '\0') {
890	                fprintf(stderr, "hybrid_handoff: invalid cosim_pc=%s\n",
891	                        tok[1]);
892	                return -1;
893	            }
894	            cosim_pc_arg = (uint64_t) v;
895	            cosim_pc_mode = 1;
896	        } else if (g_strcmp0(tok[0], "lockstep_pc") == 0 && tok[1]) {
897	            char *endp = NULL;
898	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
899	            if (!endp || *endp != '\0') {
900	                fprintf(stderr, "hybrid_handoff: invalid lockstep_pc=%s\n",
901	                        tok[1]);
902	                return -1;
903	            }
904	            lockstep_pc_arg = (uint64_t) v;
905	            lockstep_pc_mode = 1;
906	        } else if (g_strcmp0(tok[0], "lockstep_max") == 0 && tok[1]) {
907	            char *endp = NULL;
908	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
909	            if (!endp || *endp != '\0') {
910	                fprintf(stderr, "hybrid_handoff: invalid lockstep_max=%s\n",
911	                        tok[1]);
912	                return -1;
913	            }
914	            lockstep_max = (uint64_t) v;
915	        } else if (g_strcmp0(tok[0], "cosim_marker") == 0 && tok[1]) {
916	            char *endp = NULL;
917	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
918	            if (!endp || *endp != '\0') {
919	                fprintf(stderr, "hybrid_handoff: invalid cosim_marker=%s\n",
920	                        tok[1]);
921	                return -1;
922	            }
923	            cosim_marker_mode = (v != 0);
924	        } else if (g_strcmp0(tok[0], "cosim_counts") == 0 && tok[1]) {
925	            g_auto(GStrv) parts = g_strsplit(tok[1], ":", -1);
926	            size_t n = g_strv_length(parts);
927	            if (n == 0) {
928	                fprintf(stderr, "hybrid_handoff: empty cosim_counts\n");
929	                return -1;
930	            }
931	            cosim_counts = g_new0(uint64_t, n);
932	            for (size_t k = 0; k < n; k++) {
933	                char *endp = NULL;
934	                unsigned long long v = g_ascii_strtoull(parts[k], &endp, 0);
935	                if (parts[k][0] == '\0' || !endp || *endp != '\0') {
936	                    fprintf(stderr,
937	                            "hybrid_handoff: invalid cosim_counts entry: %s\n",
938	                            parts[k]);
939	                    return -1;
940	                }
941	                if (k > 0 && v <= cosim_counts[k - 1]) {
942	                    fprintf(stderr, "hybrid_handoff: cosim_counts must be "
943	                                    "strictly ascending\n");
944	                    return -1;
945	                }
946	                cosim_counts[k] = (uint64_t) v;
947	            }
948	            cosim_n_counts = n;
949	        } else if (g_strcmp0(tok[0], "drain_at_exit") == 0 && tok[1]) {
950	            // F14: any non-zero value enables. "1" is the canonical form
951	            // hsim emits; other ints (incl. negatives parsed as huge unsigned)
952	            // also enable -- the flag is a binary switch, not a count.
953	            char *endp = NULL;
954	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
955	            if (!endp || *endp != '\0') {
956	                fprintf(stderr, "hybrid_handoff: invalid drain_at_exit=%s\n",
957	                        tok[1]);
958	                return -1;
959	            }
960	            drain_at_exit_mode = (v != 0);
961	        } else {
962	            fprintf(stderr, "hybrid_handoff: unknown option: %s\n", argv[i]);
963	            return -1;
964	        }
965	    }
966	    if (!outfile_path) {
967	        fputs("hybrid_handoff: outfile=PATH is required\n", stderr);
968	        return -1;
969	    }
970	    if (pc_mode) {
971	        fprintf(stderr,
972	                "hybrid_handoff: PC-mode enter=0x%" PRIx64 "\n",
973	                enter_pc_arg);
974	    }
975	    if (icount_mode) {
976	        fprintf(stderr,
977	                "hybrid_handoff: icount-mode target=%" PRIu64 "\n",
978	                icount_target);
979	    }
980	    if (bbv_mode) {
981	        if (bbv_slice_target == 0) {
982	            fputs("hybrid_handoff: bbv_out= requires slice=N\n", stderr);
983	            return -1;
984	        }
985	        bbv_emit = bbv_emit_new(bbv_out_path, bbv_slice_target);
986	        if (!bbv_emit) {
987	            fprintf(stderr, "hybrid_handoff: failed to open bbv_out=%s\n",
988	                    bbv_out_path);
989	            return -1;
990	        }
991	        fprintf(stderr,
992	                "hybrid_handoff: bbv-mode out=%s slice=%" PRIu64 "\n",
993	                bbv_out_path, bbv_slice_target);
994	    }
995	    if (slice_consume_mode) {
996	        if (bbv_slice_target == 0) {
997	            fputs("hybrid_handoff: slice_at= requires slice=N\n", stderr);
998	            return -1;
999	        }
1000	        fprintf(stderr,
1001	                "hybrid_handoff: slice-consume mode slice=%" PRIu64
1002	                " slice_at=%" PRIu64 "\n",
1003	                bbv_slice_target, slice_at_target);
1004	    }
1005	    if (drain_at_exit_mode) {
1006	        fputs("hybrid_handoff: drain-at-exit mode enabled\n", stderr);
1007	        qemu_plugin_register_atexit_cb(id, on_atexit, NULL);
1008	    }
1009	    if (exit_marker_mode || exit_pc_mode) {
1010	        if ((exit_marker_mode && exit_pc_mode) || pc_mode || icount_mode
1011	            || bbv_mode || slice_consume_mode || drain_at_exit_mode
1012	            || cosim_marker_mode || cosim_pc_mode) {
1013	            fputs("hybrid_handoff: oracle exit drain (exit_marker/exit_pc) "
1014	                  "is exclusive with the other trigger modes\n", stderr);
1015	            return -1;
1016	        }
1017	        if (exit_pc_mode) {
1018	            fprintf(stderr,
1019	                    "hybrid_handoff: oracle exit-drain mode exit_pc=0x%"
1020	                    PRIx64 "\n", exit_pc_arg);
1021	        } else {
1022	            fputs("hybrid_handoff: oracle exit-drain mode (exit marker)\n",
1023	                  stderr);
1024	        }
1025	        if (drain_pc_set) {
1026	            fprintf(stderr, "hybrid_handoff: oracle drain_pc=0x%" PRIx64 "\n",
1027	                    drain_pc_arg);
1028	        }
1029	    } else if (drain_pc_set) {
1030	        fputs("hybrid_handoff: drain_pc requires oracle exit-drain mode "
1031	              "(exit_marker/exit_pc)\n", stderr);
1032	        return -1;
1033	    }
1034	    if (cosim_marker_mode || cosim_pc_mode) {
1035	        if ((cosim_marker_mode && cosim_pc_mode) || pc_mode || icount_mode
1036	            || bbv_mode || slice_consume_mode || drain_at_exit_mode) {
1037	            fputs("hybrid_handoff: cosim mode (cosim_marker/cosim_pc) is "
1038	                  "exclusive with the other trigger modes\n", stderr);
1039	            return -1;
1040	        }
1041	        if (cosim_n_counts == 0) {
1042	            fputs("hybrid_handoff: cosim mode requires cosim_counts=a:b:...\n",
1043	                  stderr);
1044	            return -1;
1045	        }
1046	        if (cosim_pc_mode) {
1047	            fprintf(stderr,
1048	                    "hybrid_handoff: cosim mode entry pc=0x%" PRIx64
1049	                    ", %zu drain count(s)\n", cosim_pc_arg, cosim_n_counts);
1050	        } else {
1051	            fprintf(stderr,
1052	                    "hybrid_handoff: cosim mode (entry marker), "
1053	                    "%zu drain count(s)\n", cosim_n_counts);
1054	        }
1055	        // Fresh stream per run: the sink appends, so stale records from a
1056	        // previous run would otherwise survive.
1057	        g_autofree char *stream = g_strdup_printf("%s.ckpts", outfile_path);
1058	        unlink(stream);
1059	    } else if (cosim_n_counts != 0) {
1060	        fputs("hybrid_handoff: cosim_counts requires cosim mode "
1061	              "(cosim_marker/cosim_pc)\n", stderr);
1062	        return -1;
1063	    }
1064	
1065	    if (lockstep_pc_mode) {
1066	        if (pc_mode || icount_mode || bbv_mode || slice_consume_mode
1067	            || drain_at_exit_mode || exit_marker_mode || exit_pc_mode
1068	            || cosim_marker_mode || cosim_pc_mode) {
1069	            fputs("hybrid_handoff: lockstep_pc is exclusive with the other "
1070	                  "trigger modes\n", stderr);
1071	            return -1;
1072	        }
1073	        // outfile IS the record stream in this mode; start it fresh.
1074	        unlink(outfile_path);
1075	        fprintf(stderr,
1076	                "hybrid_handoff: lockstep mode, arm pc=0x%" PRIx64
1077	                ", max records=%" PRIu64 " (0 = until exit), stream=%s\n",
1078	                lockstep_pc_arg, lockstep_max, outfile_path);
1079	    } else if (lockstep_max != 0) {
1080	        fputs("hybrid_handoff: lockstep_max requires lockstep_pc\n", stderr);
1081	        return -1;
1082	    }
1083	
1084	    vcpu_state = qemu_plugin_scoreboard_new(sizeof(VcpuRegs));
1085	    qemu_plugin_register_vcpu_tb_trans_cb(id, vcpu_tb_trans);
1086	    return 0;
1087	}
