// QEMU TCG plugin: drains architectural state and exits when the guest
// executes the ROI enter marker `slti x0, x0, 0x5A0` (a HINT NOP). Shares
// hybrid/insn_match.h and hybrid/state_abi.h with the vsim side.

#include "hybrid/handoff_site.h"
#include "hybrid/insn_match.h"
#include "hybrid/reg_names.h"
#include "hybrid/state_abi.h"
#include "hybrid/v_drain_policy.h"

#include "bbv_emit.h"

#include <qemu-plugin.h>

#include <glib.h>

#include <fcntl.h>
#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <limits.h>

QEMU_PLUGIN_EXPORT int qemu_plugin_version = QEMU_PLUGIN_VERSION;

typedef struct {
    struct qemu_plugin_register *gpr[32];
    struct qemu_plugin_register *fpr[32];
    struct qemu_plugin_register *fcsr;  // L20: frm[7:5] | fflags[4:0]
    struct qemu_plugin_register *pc;
    struct qemu_plugin_register *priv;  // L6: gdbstub virtual feature

    // M-mode CSRs as exposed by QEMU's gdbstub csr feature.
    struct qemu_plugin_register *mstatus;
    struct qemu_plugin_register *mepc;
    struct qemu_plugin_register *mtvec;
    struct qemu_plugin_register *mcause;
    struct qemu_plugin_register *mtval;
    struct qemu_plugin_register *mscratch;
    struct qemu_plugin_register *medeleg;
    struct qemu_plugin_register *mideleg;
    struct qemu_plugin_register *mip;
    struct qemu_plugin_register *mie;
    struct qemu_plugin_register *mcycle;
    struct qemu_plugin_register *minstret;
    struct qemu_plugin_register *satp;

    struct qemu_plugin_register *pmpcfg[HYBRID_PMP_CFG_NUM];
    struct qemu_plugin_register *pmpaddr[HYBRID_PMP_ADDR_NUM];

    struct qemu_plugin_register *vstart;
    struct qemu_plugin_register *vxsat;
    struct qemu_plugin_register *vxrm;
    struct qemu_plugin_register *vcsr;
    struct qemu_plugin_register *vtype;
    struct qemu_plugin_register *vl;
    struct qemu_plugin_register *vlenb;
    struct qemu_plugin_register *vreg[32];

    // icount-trigger mode: per-vcpu retired-insn counter, incremented in
    // on_icount_tick. When icount_target is reached, the same drain path
    // as CSR/PC mode fires (on_handoff -> write_state_atomic -> exit 200).
    uint64_t icount_retired;
} VcpuRegs;

static struct qemu_plugin_scoreboard *vcpu_state;
static char *outfile_path;

// PC-trigger mode: when enter_pc_arg is non-zero (set via plugin arg
// `enter_pc=0x...`), the CSR-insn matcher is bypassed entirely and the
// drain callback is registered only for instructions whose vaddr equals
// enter_pc_arg. The kind reported on the drain is HYBRID_HANDOFF_ENTER
// (entry into vsim), matching marker-mode enter-marker semantics.
static uint64_t enter_pc_arg;
static int pc_mode;

// icount-trigger mode: when icount_target is non-zero (set via plugin arg
// `icount=N`), every translated insn gets an exec callback that bumps a
// per-vcpu counter; on threshold-cross the drain fires at that insn
// boundary. Coexists with CSR/PC modes - either trigger can win.
static uint64_t icount_target;
static int icount_mode;

// BBV-emit mode (SimPoint profile): when bbv_mode is set (plugin args
// `bbv_out=PATH,slice=N`), every translated insn gets an exec callback
// that ticks a global BBV counter; one .bb row per N retired insns is
// flushed to PATH. Coexists with the drain triggers - independently
// registered before icount so that on co-firing (icount target == slice
// multiple) the slice row is emitted before exit(200).
static BbvEmit *bbv_emit;
static char    *bbv_out_path;
static uint64_t bbv_slice_target;
static int      bbv_mode;

// Slice-consume mode (SimPoint replay; F11): when slice_consume_mode is
// set (plugin args `slice=N,slice_at=K`), the plugin counts slice
// boundaries (one boundary per N retired insns) and drains at the end
// of slice index K (0-based). With K=2 and slice=1000, drain fires at
// insn 3000 - the boundary that closes the third slice. The orchestrator
// chains one invocation per SimPoint cluster-representative slice idx.
// Shares the `slice=` parameter with BBV-emit; works independently of
// whether `bbv_out=` is also set.
static uint64_t slice_at_target;
static int      slice_consume_mode;
static uint64_t slice_consume_acc;
static uint64_t slice_consume_idx;

// Drain-at-exit mode (F14): when drain_at_exit_mode is set (plugin arg
// `drain_at_exit=1`), the plugin registers a per-insn exec callback that
// bumps `atexit_insn_count`, and a `qemu_plugin_register_atexit_cb` that
// drains state on natural program exit (e.g. semihosting EXIT). The
// atexit callback overrides s.minstret with the plugin counter so the
// caller (./hsim estimate --icount 0) gets a true retired-insn count
// independent of QEMU's PMU semantics (which can return host ticks on
// system-mode without `-icount`). `drained_already` suppresses the
// atexit path if any other trigger (CSR/PC/icount/slice) drained first.
static int      drain_at_exit_mode;
static volatile int drained_already;
static uint64_t atexit_insn_count;

// Oracle exit-drain mode (verify_oracle F1): when exit_marker_mode or
// exit_pc_mode is set (plugin args `exit_marker=1` / `exit_pc=0x...`), a
// pure-QEMU run produces the differential verifier's reference state. Every
// insn gets an exec callback (icount-mode cost class): the tick ARMS on the
// ROI exit boundary (EXIT marker match, or vaddr == exit_pc) and DRAINS on
// the next callback. Exec callbacks fire before their insn executes, so the
// armed drain captures "after the boundary insn retired" -- exactly vsim's
// exit-drain record (DPC = next insn to execute) -- and reports that next
// insn's vaddr as pc, correct even when the boundary insn branches.
// Exclusive with the other trigger modes: the oracle run never hands off.
//
// drain_pc=0x... (optional modifier): drain at the first post-arm tick whose
// vaddr equals drain_pc, instead of the very next tick. The differential
// harness passes vsim's actual drained pc here: vsim's DMI halt lands a
// variable 0-3 insns past the trigger (the core keeps retiring while the
// haltreq propagates), and the two states only compare equal when both
// sides sample the SAME architectural point. If vsim's pc is never reached
// (a real control-flow divergence), the oracle never drains and QEMU runs
// to completion -- the caller sees exit != 200.
static uint64_t exit_pc_arg;
static int      exit_pc_mode;
static int      exit_marker_mode;
static uint64_t drain_pc_arg;
static int      drain_pc_set;
static volatile int oracle_armed;

// Cosim oracle mode (cosim_roi F3): when cosim_marker_mode or cosim_pc_mode
// is set (plugin args `cosim_marker=1` / `cosim_pc=0x...`), a per-insn exec
// callback ARMS at the ROI entry boundary, then drains hybrid_state_v1 at
// the post-entry retire counts listed in cosim_counts=a:b:c (strictly
// ascending). Every count but the last writes <outfile>.ckpt<k> (k from 1)
// and execution continues; the LAST drains <outfile> and exits 200. The
// counts come from the vsim leg's checkpoint minstret deltas, so both
// engines sample the SAME architectural points (see cosim_roi.md).
//
// Counting mirrors the vsim leg's minstret reference point:
//   marker mode: the ENTER marker is counted by NEITHER side (QEMU1 drains
//     pre-marker, vsim resumes past it) -- the arming tick does not count.
//   pc mode: the boundary insn retires INSIDE the window (the pc-mode
//     handoff resumes AT the boundary), so the arming tick counts it.
// Exclusive with every other trigger mode (including the exit oracle).
static uint64_t *cosim_counts;
static size_t    cosim_n_counts;
static uint64_t  cosim_pc_arg;
static int       cosim_pc_mode;
static int       cosim_marker_mode;
static volatile int cosim_armed;
static uint64_t  cosim_done;   // post-entry retires so far
static size_t    cosim_idx;    // next cosim_counts[] target

// Lock-step oracle mode (cosim_redesign F5): `lockstep_pc=0x...` arms at
// the given vaddr, then drains the full state BEFORE every execution
// attempt, appending each record to the `outfile` stream (outfile IS the
// stream in this mode; there is no separate final state file). Exec
// callbacks fire pre-execution, so record k = state before attempt k+1 --
// the exact point where vsim's dcsr.step halt lands, traps included (a
// trapped attempt's next callback is the handler entry on both sides).
// Stops at `lockstep_max=K` records (exit 200) or at natural program exit.
static uint64_t  lockstep_pc_arg;
static int       lockstep_pc_mode;
static uint64_t  lockstep_max;
static volatile int lockstep_armed;
static uint64_t  lockstep_count;

static struct qemu_plugin_register *find_reg(GArray *regs, const char *name)
{
    for (guint i = 0; i < regs->len; i++) {
        qemu_plugin_reg_descriptor *rd =
            &g_array_index(regs, qemu_plugin_reg_descriptor, i);
        if (g_ascii_strcasecmp(rd->name, name) == 0) {
            return rd->handle;
        }
    }
    return NULL;
}

// Lazily resolves register handles. The plugin's vcpu_init runs before
// QEMU has registered the dynamic gdb coprocessors (FPU, virtual, csr,
// vector), so qemu_plugin_get_registers() returns only the 33 core CPU
// regs at that moment. By the time the entry trigger fires, all dynamic
// features are registered and a fresh call returns the full list.
static void resolve_handles(VcpuRegs *v)
{
    g_autoptr(GArray) regs = qemu_plugin_get_registers();
    for (int i = 0; i < 32; i++) {
        v->gpr[i] = find_reg(regs, hybrid_gpr_names[i]);
        v->fpr[i] = find_reg(regs, hybrid_fpr_names[i]);
    }
    v->fcsr = find_reg(regs, "fcsr");
    v->pc = find_reg(regs, "pc");
    v->priv = find_reg(regs, "priv");

    v->mstatus  = find_reg(regs, "mstatus");
    v->mepc     = find_reg(regs, "mepc");
    v->mtvec    = find_reg(regs, "mtvec");
    v->mcause   = find_reg(regs, "mcause");
    v->mtval    = find_reg(regs, "mtval");
    v->mscratch = find_reg(regs, "mscratch");
    v->medeleg  = find_reg(regs, "medeleg");
    v->mideleg  = find_reg(regs, "mideleg");
    v->mip      = find_reg(regs, "mip");
    v->mie      = find_reg(regs, "mie");
    v->mcycle   = find_reg(regs, "mcycle");
    v->minstret = find_reg(regs, "minstret");
    v->satp     = find_reg(regs, "satp");

    char buf[16];
    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++) {
        g_snprintf(buf, sizeof(buf), "pmpcfg%d", i);
        v->pmpcfg[i] = find_reg(regs, buf);
    }
    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++) {
        g_snprintf(buf, sizeof(buf), "pmpaddr%d", i);
        v->pmpaddr[i] = find_reg(regs, buf);
    }

    v->vstart = find_reg(regs, "vstart");
    v->vxsat  = find_reg(regs, "vxsat");
    v->vxrm   = find_reg(regs, "vxrm");
    v->vcsr   = find_reg(regs, "vcsr");
    v->vtype  = find_reg(regs, "vtype");
    v->vl     = find_reg(regs, "vl");
    v->vlenb  = find_reg(regs, "vlenb");
    for (int i = 0; i < 32; i++) {
        g_snprintf(buf, sizeof(buf), "v%d", i);
        v->vreg[i] = find_reg(regs, buf);
    }
}

static uint64_t read_reg64(struct qemu_plugin_register *h)
{
    if (!h) return 0;
    g_autoptr(GByteArray) buf = g_byte_array_new();
    int sz = qemu_plugin_read_register(h, buf);
    if (sz <= 0) return 0;
    uint64_t v = 0;
    memcpy(&v, buf->data, sz < 8 ? (size_t) sz : 8);
    return v;
}

// Reads up to `dst_max` bytes from a register handle. Returns the byte
// count written (0 on failure or NULL handle). Used for vector regs whose
// width = vlenb bytes.
static size_t read_reg_bytes(struct qemu_plugin_register *h,
                             uint8_t *dst, size_t dst_max)
{
    if (!h || dst_max == 0) return 0;
    g_autoptr(GByteArray) buf = g_byte_array_new();
    int sz = qemu_plugin_read_register(h, buf);
    if (sz <= 0) return 0;
    size_t n = (size_t) sz < dst_max ? (size_t) sz : dst_max;
    memcpy(dst, buf->data, n);
    return n;
}

// Atomic on POSIX: write to a mkstemp-reserved tmp file, fsync, rename.
// mkstemp guarantees uniqueness via a 6-char random suffix + atomic
// O_EXCL-style inode reservation, so concurrent plugin instances cannot
// collide even under aggressive PID reuse (B13). The tmp lives in the
// same directory as `path` so the rename is intra-filesystem.
static int write_state_atomic(const struct hybrid_state_v1 *s, const char *path)
{
    char tmp[PATH_MAX];
    int n = g_snprintf(tmp, sizeof(tmp), "%s.tmp.XXXXXX", path);
    if (n < 0 || (size_t) n >= sizeof(tmp)) {
        fprintf(stderr, "hybrid_handoff: tmp path too long\n");
        return -1;
    }
    int fd = g_mkstemp(tmp);
    if (fd < 0) {
        perror("hybrid_handoff: g_mkstemp");
        return -1;
    }
    // g_mkstemp creates the file 0600; no further chmod needed.
    ssize_t want = (ssize_t) sizeof(*s);
    ssize_t got = write(fd, s, sizeof(*s));
    if (got != want) {
        perror("hybrid_handoff: write");
        close(fd);
        unlink(tmp);
        return -1;
    }
    fsync(fd);
    close(fd);
    if (rename(tmp, path) != 0) {
        perror("hybrid_handoff: rename");
        unlink(tmp);
        return -1;
    }
    return 0;
}

// Append one record to a `.ckpts` stream (concatenated hybrid_state_v1,
// cosim_redesign F3). No tmp-rename dance: the stream has a single writer
// and readers only run after the producer exits.
static int append_state_stream(const struct hybrid_state_v1 *s,
                               const char *path)
{
    FILE *f = fopen(path, "ab");
    if (!f) {
        perror("hybrid_handoff: fopen stream");
        return -1;
    }
    const size_t n = fwrite(s, 1, sizeof(*s), f);
    fclose(f);
    return n == sizeof(*s) ? 0 : -1;
}

// Drain CPU state into `*s`. pc is computed by the caller (from a
// HandoffSite for trigger paths, or 0 for the atexit path which lacks an
// insn context). If minstret_override is non-zero, it replaces QEMU's PMU
// minstret (used by drain_at_exit mode to record a plugin-counted
// retired-insn total).
static void drain_state_into(unsigned int vcpu_idx, uint64_t pc,
                             uint64_t minstret_override,
                             struct hybrid_state_v1 *sp)
{
    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
    resolve_handles(v);
    memset(sp, 0, sizeof(*sp));
    struct hybrid_state_v1 s = {0};
    s.magic   = HYBRID_STATE_MAGIC;
    s.version = HYBRID_STATE_VERSION;
    s.flags   = HYBRID_FLAG_RV64;
    s.hart_id = vcpu_idx;
    // L6: real privilege at the boundary; M-mode fallback only when the
    // stub doesn't advertise the gdbstub virtual feature (a missing handle
    // reads as 0 = U, which would silently demote the hart).
    s.priv    = v->priv ? (read_reg64(v->priv) & 0x3) : 3;
    s.pc      = pc;
    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);

    // Floating-point: only set FP flag if at least one handle was bound,
    // i.e. QEMU advertised the FPU feature (D extension).
    int has_fp = 0;
    for (int i = 0; i < 32; i++) {
        s.fpr[i] = read_reg64(v->fpr[i]);
        if (v->fpr[i]) has_fp = 1;
    }
    if (has_fp) s.flags |= HYBRID_FLAG_FP;
    s.fcsr = read_reg64(v->fcsr);  // L20: rides HYBRID_FLAG_FP

    s.mstatus  = read_reg64(v->mstatus);
    s.mepc     = read_reg64(v->mepc);
    s.mtvec    = read_reg64(v->mtvec);
    s.mcause   = read_reg64(v->mcause);
    s.mtval    = read_reg64(v->mtval);
    s.mscratch = read_reg64(v->mscratch);
    s.medeleg  = read_reg64(v->medeleg);
    s.mideleg  = read_reg64(v->mideleg);
    s.mip      = read_reg64(v->mip);
    s.mie      = read_reg64(v->mie);
    s.mcycle   = read_reg64(v->mcycle);
    s.minstret = minstret_override ? minstret_override
                                   : read_reg64(v->minstret);
    s.satp     = read_reg64(v->satp);

    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);

    // Vector: only set V flag if QEMU advertised the V extension. vlenb
    // bounds the per-register byte count copied into vreg[]. The policy
    // helper (hybrid_v_drain_policy) decides SKIP/OK/ABORT from the
    // handle truthiness so we don't conflate "stub missing vlenb" with
    // "V disabled at runtime"; see include/hybrid/v_drain_policy.h.
    s.vstart = read_reg64(v->vstart);
    s.vxsat  = read_reg64(v->vxsat);
    s.vxrm   = read_reg64(v->vxrm);
    s.vcsr   = read_reg64(v->vcsr);
    s.vtype  = read_reg64(v->vtype);
    s.vl     = read_reg64(v->vl);
    s.vlenb  = read_reg64(v->vlenb);
    int has_other_v = (v->vstart || v->vxsat || v->vxrm || v->vcsr
                       || v->vtype || v->vl);
    if (!has_other_v) {
        for (int i = 0; i < 32; i++)
            if (v->vreg[i]) { has_other_v = 1; break; }
    }
    HybridVDrainPolicy vpol = hybrid_v_drain_policy(
        v->vlenb != NULL, has_other_v, s.vlenb);
    if (vpol == HYBRID_V_DRAIN_ABORT) {
        if (v->vlenb == NULL)
            fprintf(stderr,
                    "hybrid_handoff: stub advertised V CSRs/regs but not "
                    "vlenb; refusing to drain partial V state\n");
        else
            fprintf(stderr,
                    "hybrid_handoff: vlenb=%" PRIu64 " exceeds the wire-format "
                    "ceiling HYBRID_VLEN_BYTES_MAX=%d (VLEN %d); refusing to "
                    "truncate V registers\n",
                    s.vlenb, HYBRID_VLEN_BYTES_MAX,
                    8 * HYBRID_VLEN_BYTES_MAX);
        exit(2);
    }
    if (vpol == HYBRID_V_DRAIN_OK) {
        s.flags |= HYBRID_FLAG_V;
        /* The policy guarantees vlenb <= HYBRID_VLEN_BYTES_MAX here, so the
         * full live register fits the wire-format slot -- no clamp (L11). */
        for (int i = 0; i < 32; i++)
            (void) read_reg_bytes(v->vreg[i],
                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
                                  (size_t) s.vlenb);
    }

    *sp = s;
}

// Drain CPU state to `path`. Does NOT call exit -- caller decides exit(200)
// (normal trigger) vs _exit(200) (inside atexit chain).
static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
                                uint64_t minstret_override, const char *path)
{
    struct hybrid_state_v1 s;
    drain_state_into(vcpu_idx, pc, minstret_override, &s);
    if (write_state_atomic(&s, path) != 0) {
        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
        exit(2);
    }
    fprintf(stderr,
            "hybrid_handoff: drained state to %s (pc=%#" PRIx64 ")\n",
            path, s.pc);
}

// Shared drain tail: capture the (pre-execution) state, report `resume_pc`
// as the vsim resume point, and exit 200.
static void handoff_drain(unsigned int vcpu_idx, uint64_t resume_pc)
{
    // F14: suppress the atexit drain path now that we have a real trigger.
    drained_already = 1;
    drain_state_to_file(vcpu_idx, resume_pc, 0, outfile_path);
    // 200 == kExitHandoffToQemu in verilator/src/hybrid/exit_codes.hpp.
    // Distinguishes drain from workload completion (0) so the orchestrator
    // can decide the next spawn.
    exit(200);
}

// Marker sites. The marker is an architectural NOP, so the pre-execution
// state equals the post-retire state and the window resumes AFTER it
// (vaddr+size, computed at translation time; reading the gdbstub PC inside
// the exec callback can lag the actual current insn when V instructions
// retire just before the trigger -- TCG defers PC writes for performance).
static void on_handoff(unsigned int vcpu_idx, void *udata)
{
    const HandoffSite *site = (const HandoffSite *) udata;
    if (site->kind != HYBRID_HANDOFF_ENTER) return;
    handoff_drain(vcpu_idx, compute_handoff_pc(site));
}

// pc/icount/slice boundary sites. Exec callbacks fire BEFORE the insn
// executes, and the boundary insn is real user code (unlike a marker NOP):
// the drained state must resume AT the boundary so the insn executes inside
// the vsim window rather than on neither leg. (Skipping it corrupts the
// window's architectural state -- e.g. a skipped vsetivli leaves vtype.vill
// set and the first vector op of the window faults.)
static void on_handoff_boundary(unsigned int vcpu_idx, void *udata)
{
    const HandoffSite *site = (const HandoffSite *) udata;
    if (site->kind != HYBRID_HANDOFF_ENTER) return;
    handoff_drain(vcpu_idx, site->vaddr);
}

// F14: per-insn tick. Increments a global counter every retired insn so the
// drain-at-exit path can report a true retired-insn total (independent of
// QEMU's PMU semantics).
static void on_count_tick(unsigned int vcpu_idx, void *udata)
{
    (void) vcpu_idx;
    (void) udata;
    atexit_insn_count++;
}

// F14: atexit drain. Fires when QEMU exits naturally (no ROI trigger). The
// record is a CONTEXT-FREE count, not an architectural drain: depending on
// the guest's exit path this callback runs on the vCPU thread (semihosting
// EXIT) or on QEMU's main loop thread (vplat/SimControl shutdown request),
// and on the main thread there is no vCPU context -- any
// qemu_plugin_read_register aborts QEMU (api.c asserts current_cpu). The
// only consumer (the SimPoint estimate profile) reads minstret = the
// plugin-side retire counter (N_total); pc=0 is the positive marker that
// the atexit path drained (no trigger). If any other trigger already
// drained, return immediately (drained_already guards against double
// drain). Inside an atexit handler, exit() is UB per C11 7.22.4.4; use
// _exit() to skip the rest of the atexit chain.
static void on_atexit(qemu_plugin_id_t id, void *udata)
{
    (void) id;
    (void) udata;
    if (drained_already) return;
    if (!drain_at_exit_mode) return;
    struct hybrid_state_v1 s = {0};
    s.magic    = HYBRID_STATE_MAGIC;
    s.version  = HYBRID_STATE_VERSION;
    s.flags    = HYBRID_FLAG_RV64;
    s.priv     = 3;
    s.minstret = atexit_insn_count;
    if (write_state_atomic(&s, outfile_path) != 0)
        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
    else
        fprintf(stderr,
                "hybrid_handoff: drained exit count record to %s "
                "(minstret=%" PRIu64 ")\n",
                outfile_path, s.minstret);
    fflush(stderr);
    _exit(200);
}

// Per-insn tick for oracle exit-drain mode. udata is this insn's HandoffSite.
// When armed (the exit boundary's own tick ran), this tick fires before its
// insn executes, so a drain here records the post-retire state of the
// boundary insn with pc = the dynamically-next insn's vaddr.
static void on_oracle_tick(unsigned int vcpu_idx, void *udata)
{
    const HandoffSite *site = (const HandoffSite *) udata;
    if (oracle_armed
        && (!drain_pc_set || site->vaddr == drain_pc_arg)) {
        handoff_drain(vcpu_idx, site->vaddr);
    }
    if (exit_pc_mode ? (site->vaddr == exit_pc_arg)
                     : (site->kind == HYBRID_HANDOFF_EXIT)) {
        oracle_armed = 1;
    }
}

// Checkpoint drain for cosim mode: append to the <outfile>.ckpts stream and
// KEEP RUNNING (no exit, drained_already untouched -- the final count uses
// handoff_drain).
static void cosim_checkpoint_drain(unsigned int vcpu_idx, uint64_t pc,
                                   size_t k)
{
    g_autofree char *path = g_strdup_printf("%s.ckpts", outfile_path);
    struct hybrid_state_v1 s;
    drain_state_into(vcpu_idx, pc, 0, &s);
    if (append_state_stream(&s, path) != 0) {
        fprintf(stderr, "hybrid_handoff: failed to append checkpoint %zu\n",
                k);
        exit(2);
    }
    fprintf(stderr,
            "hybrid_handoff: checkpoint %zu appended to %s (pc=%#" PRIx64
            ")\n", k, path, s.pc);
}

// Per-insn tick for cosim mode. udata is this insn's HandoffSite. Exec
// callbacks fire pre-execution: at an armed tick, `cosim_done` post-entry
// insns have retired and the current insn has not, so draining when
// cosim_done == target captures "entry + target retires" with pc = the
// dynamically-next insn's vaddr -- the same point as the vsim checkpoint's
// DPC at minstret delta == target.
static void on_cosim_tick(unsigned int vcpu_idx, void *udata)
{
    const HandoffSite *site = (const HandoffSite *) udata;
    if (!cosim_armed) {
        if (cosim_pc_mode ? (site->vaddr == cosim_pc_arg)
                          : (site->kind == HYBRID_HANDOFF_ENTER)) {
            cosim_armed = 1;
            // Marker mode: the marker is counted by neither side -- done.
            // pc mode: the boundary insn retires inside the window (the
            // handoff resumes AT it) -- fall through and count this tick.
            if (!cosim_pc_mode) return;
        } else {
            return;
        }
    }
    if (cosim_idx < cosim_n_counts && cosim_done == cosim_counts[cosim_idx]) {
        if (cosim_idx + 1 == cosim_n_counts)
            handoff_drain(vcpu_idx, site->vaddr);  // final: exits 200
        else
            cosim_checkpoint_drain(vcpu_idx, site->vaddr, cosim_idx + 1);
        cosim_idx++;
    }
    cosim_done++;
}

// Per-insn tick for lock-step oracle mode. udata is this insn's
// HandoffSite. Drains BEFORE the insn executes (record k = state before
// attempt k+1) and appends to the outfile stream.
static void on_lockstep_tick(unsigned int vcpu_idx, void *udata)
{
    const HandoffSite *site = (const HandoffSite *) udata;
    if (!lockstep_armed) {
        if (site->vaddr != lockstep_pc_arg) return;
        lockstep_armed = 1;
    }
    struct hybrid_state_v1 s;
    drain_state_into(vcpu_idx, site->vaddr, 0, &s);
    if (append_state_stream(&s, outfile_path) != 0) {
        fprintf(stderr, "hybrid_handoff: failed to append lockstep record "
                "%" PRIu64 "\n", lockstep_count);
        exit(2);
    }
    lockstep_count++;
    if (lockstep_max != 0 && lockstep_count >= lockstep_max) {
        drained_already = 1;
        fprintf(stderr,
                "hybrid_handoff: lockstep done, %" PRIu64 " record(s) in "
                "%s\n", lockstep_count, outfile_path);
        fflush(stderr);
        exit(200);
    }
}

// Per-insn tick for icount mode. udata is the per-insn HandoffSite
// pre-allocated at translation time, so on_handoff's compute_handoff_pc
// returns the lag-free post-trigger PC (same property as the CSR path).
static void on_icount_tick(unsigned int vcpu_idx, void *udata)
{
    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
    if (++v->icount_retired < icount_target) return;
    on_handoff_boundary(vcpu_idx, udata);
}

// Per-insn tick for BBV-emit mode. udata is the bb_id (1-based) cast to
// pointer; that mapping is stable across calls because bbv_emit_assign_id
// is hashed by TB-start PC. The tick attributes one insn to the bb_id and
// flushes a slice row when the per-slice counter saturates.
static void on_bbv_tick(unsigned int vcpu_idx, void *udata)
{
    (void) vcpu_idx;
    uint64_t bb_id = (uint64_t) GPOINTER_TO_UINT(udata);
    bbv_emit_tick(bbv_emit, bb_id);
}

// Per-insn tick for slice-consume mode (F11). Counts insns into the
// slice accumulator; on each slice boundary increments slice_consume_idx
// and resets the accumulator. Once slice_consume_idx exceeds the target
// slice index, drains via on_handoff at that same insn boundary. udata
// is the per-insn HandoffSite (allocated at translation time) so the
// post-trigger PC reaches on_handoff lag-free.
static void on_slice_consume_tick(unsigned int vcpu_idx, void *udata)
{
    if (++slice_consume_acc < bbv_slice_target) return;
    slice_consume_acc = 0;
    if (slice_consume_idx++ < slice_at_target) return;
    // After the post-increment above, slice_consume_idx == slice_at_target+1
    // (the count of fully retired slices). Log so the e2e test can verify
    // drain timing without relying on minstret (which is a cycle-counter
    // proxy on andes-ax45mpv and does not track plugin-counted insns).
    fprintf(stderr,
            "hybrid_handoff: slice-consume drain (idx=%" PRIu64
            " target=%" PRIu64 ")\n",
            slice_consume_idx, slice_at_target);
    on_handoff_boundary(vcpu_idx, udata);
}

static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
{
    (void) id;
    size_t n = qemu_plugin_tb_n_insns(tb);

    // BBV-mode: assign a stable bb_id to this TB (1-based, hashed by
    // TB-start vaddr). Same id is shared by every insn in the TB.
    uint64_t bb_id = 0;
    if (bbv_mode && n > 0) {
        uint64_t tb_pc = qemu_plugin_insn_vaddr(qemu_plugin_tb_get_insn(tb, 0));
        bb_id = bbv_emit_assign_id(bbv_emit, tb_pc);
    }

    for (size_t i = 0; i < n; i++) {
        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);

        // Oracle exit-drain mode: exclusive with every other mode (enforced
        // at install), so it owns the insn's registration outright. The site
        // carries the marker kind so the tick can arm on the EXIT marker.
        if (exit_marker_mode || exit_pc_mode) {
            HandoffSite *site = g_new0(HandoffSite, 1);
            site->kind  = HYBRID_HANDOFF_NONE;
            site->vaddr = qemu_plugin_insn_vaddr(insn);
            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
            if (exit_marker_mode && site->size == 4) {
                uint32_t raw = 0;
                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
                    hybrid_match_handoff_insn(raw, &site->kind);
            }
            qemu_plugin_register_vcpu_insn_exec_cb(
                insn, on_oracle_tick, QEMU_PLUGIN_CB_R_REGS, site);
            continue;
        }

        // Cosim oracle mode: exclusive with every other mode (enforced at
        // install). Same site shape as the exit oracle; kind carries the
        // marker match so the tick can arm on the ENTER marker.
        if (cosim_marker_mode || cosim_pc_mode) {
            HandoffSite *site = g_new0(HandoffSite, 1);
            site->kind  = HYBRID_HANDOFF_NONE;
            site->vaddr = qemu_plugin_insn_vaddr(insn);
            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
            if (cosim_marker_mode && site->size == 4) {
                uint32_t raw = 0;
                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
                    hybrid_match_handoff_insn(raw, &site->kind);
            }
            qemu_plugin_register_vcpu_insn_exec_cb(
                insn, on_cosim_tick, QEMU_PLUGIN_CB_R_REGS, site);
            continue;
        }

        // Lock-step oracle mode: exclusive with every other mode (enforced
        // at install). Every insn ticks; the tick arms at lockstep_pc.
        if (lockstep_pc_mode) {
            HandoffSite *site = g_new0(HandoffSite, 1);
            site->kind  = HYBRID_HANDOFF_NONE;
            site->vaddr = qemu_plugin_insn_vaddr(insn);
            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
            qemu_plugin_register_vcpu_insn_exec_cb(
                insn, on_lockstep_tick, QEMU_PLUGIN_CB_R_REGS, site);
            continue;
        }

        // F14 count tick: registered FIRST so the count is incremented
        // before any trigger callback can call exit(200). NO_REGS keeps
        // the per-insn cost minimal (a single uint64 add).
        if (drain_at_exit_mode) {
            qemu_plugin_register_vcpu_insn_exec_cb(
                insn, on_count_tick, QEMU_PLUGIN_CB_NO_REGS, NULL);
        }

        // BBV callback is registered BEFORE icount so that if both modes
        // fire on the same insn (icount target == slice multiple), the
        // slice row is emitted before exit(200) is called.
        if (bbv_mode) {
            qemu_plugin_register_vcpu_insn_exec_cb(
                insn, on_bbv_tick, QEMU_PLUGIN_CB_NO_REGS,
                GUINT_TO_POINTER((guint) bb_id));
        }

        // Slice-consume callback (F11). Registered after BBV so a BBV
        // row at the same boundary is flushed first; ordering vs icount
        // is irrelevant (both drain).
        if (slice_consume_mode) {
            HandoffSite *site = g_new0(HandoffSite, 1);
            site->kind  = HYBRID_HANDOFF_ENTER;
            site->vaddr = qemu_plugin_insn_vaddr(insn);
            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
            qemu_plugin_register_vcpu_insn_exec_cb(
                insn, on_slice_consume_tick, QEMU_PLUGIN_CB_R_REGS, site);
        }

        if (icount_mode) {
            HandoffSite *site = g_new0(HandoffSite, 1);
            site->kind  = HYBRID_HANDOFF_ENTER;
            site->vaddr = qemu_plugin_insn_vaddr(insn);
            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
            qemu_plugin_register_vcpu_insn_exec_cb(
                insn, on_icount_tick, QEMU_PLUGIN_CB_R_REGS, site);
        }

        if (pc_mode) {
            // PC-trigger mode: vaddr-only match; the drain resumes AT the
            // boundary (on_handoff_boundary), so the insn size is recorded
            // only for completeness.
            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
            HandoffSite *site = g_new0(HandoffSite, 1);
            site->kind  = HYBRID_HANDOFF_ENTER;
            site->vaddr = qemu_plugin_insn_vaddr(insn);
            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
            qemu_plugin_register_vcpu_insn_exec_cb(
                insn, on_handoff_boundary, QEMU_PLUGIN_CB_R_REGS, site);
            continue;
        }

        // Marker-trigger mode (default).
        // The markers are `slti x0, x0, 0x5A0/0x5A1`, always 32-bit
        // (sz==4): SLTI has no compressed form, so the sz!=4 skip is
        // exact, not an approximation.
        size_t sz = qemu_plugin_insn_size(insn);
        if (sz != 4) continue;
        uint32_t raw = 0;
        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
            continue;
        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
        HandoffSite *site = g_new0(HandoffSite, 1);
        site->kind  = kind;
        site->vaddr = qemu_plugin_insn_vaddr(insn);
        site->size  = (uint32_t) sz;
        qemu_plugin_register_vcpu_insn_exec_cb(
            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
    }
}

QEMU_PLUGIN_EXPORT int qemu_plugin_install(qemu_plugin_id_t id,
                                           const qemu_info_t *info,
                                           int argc, char **argv)
{
    (void) info;
    for (int i = 0; i < argc; i++) {
        g_auto(GStrv) tok = g_strsplit(argv[i], "=", 2);
        if (g_strcmp0(tok[0], "outfile") == 0 && tok[1]) {
            outfile_path = g_strdup(tok[1]);
        } else if (g_strcmp0(tok[0], "enter_pc") == 0 && tok[1]) {
            char *endp = NULL;
            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
            if (!endp || *endp != '\0') {
                fprintf(stderr, "hybrid_handoff: invalid enter_pc=%s\n",
                        tok[1]);
                return -1;
            }
            enter_pc_arg = (uint64_t) v;
            pc_mode = 1;
        } else if (g_strcmp0(tok[0], "icount") == 0 && tok[1]) {
            char *endp = NULL;
            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
            if (!endp || *endp != '\0' || v == 0) {
                fprintf(stderr, "hybrid_handoff: invalid icount=%s\n",
                        tok[1]);
                return -1;
            }
            icount_target = (uint64_t) v;
            icount_mode = 1;
        } else if (g_strcmp0(tok[0], "bbv_out") == 0 && tok[1]) {
            bbv_out_path = g_strdup(tok[1]);
            bbv_mode = 1;
        } else if (g_strcmp0(tok[0], "slice") == 0 && tok[1]) {
            char *endp = NULL;
            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
            if (!endp || *endp != '\0' || v == 0) {
                fprintf(stderr, "hybrid_handoff: invalid slice=%s\n",
                        tok[1]);
                return -1;
            }
            bbv_slice_target = (uint64_t) v;
        } else if (g_strcmp0(tok[0], "slice_at") == 0 && tok[1]) {
            char *endp = NULL;
            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
            if (!endp || *endp != '\0') {
                fprintf(stderr, "hybrid_handoff: invalid slice_at=%s\n",
                        tok[1]);
                return -1;
            }
            slice_at_target = (uint64_t) v;
            slice_consume_mode = 1;
        } else if (g_strcmp0(tok[0], "exit_pc") == 0 && tok[1]) {
            char *endp = NULL;
            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
            if (!endp || *endp != '\0') {
                fprintf(stderr, "hybrid_handoff: invalid exit_pc=%s\n",
                        tok[1]);
                return -1;
            }
            exit_pc_arg = (uint64_t) v;
            exit_pc_mode = 1;
        } else if (g_strcmp0(tok[0], "exit_marker") == 0 && tok[1]) {
            char *endp = NULL;
            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
            if (!endp || *endp != '\0') {
                fprintf(stderr, "hybrid_handoff: invalid exit_marker=%s\n",
                        tok[1]);
                return -1;
            }
            exit_marker_mode = (v != 0);
        } else if (g_strcmp0(tok[0], "drain_pc") == 0 && tok[1]) {
            char *endp = NULL;
            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
            if (!endp || *endp != '\0') {
                fprintf(stderr, "hybrid_handoff: invalid drain_pc=%s\n",
                        tok[1]);
                return -1;
            }
            drain_pc_arg = (uint64_t) v;
            drain_pc_set = 1;
        } else if (g_strcmp0(tok[0], "cosim_pc") == 0 && tok[1]) {
            char *endp = NULL;
            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
            if (!endp || *endp != '\0') {
                fprintf(stderr, "hybrid_handoff: invalid cosim_pc=%s\n",
                        tok[1]);
                return -1;
            }
            cosim_pc_arg = (uint64_t) v;
            cosim_pc_mode = 1;
        } else if (g_strcmp0(tok[0], "lockstep_pc") == 0 && tok[1]) {
            char *endp = NULL;
            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
            if (!endp || *endp != '\0') {
                fprintf(stderr, "hybrid_handoff: invalid lockstep_pc=%s\n",
                        tok[1]);
                return -1;
            }
            lockstep_pc_arg = (uint64_t) v;
            lockstep_pc_mode = 1;
        } else if (g_strcmp0(tok[0], "lockstep_max") == 0 && tok[1]) {
            char *endp = NULL;
            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
            if (!endp || *endp != '\0') {
                fprintf(stderr, "hybrid_handoff: invalid lockstep_max=%s\n",
                        tok[1]);
                return -1;
            }
            lockstep_max = (uint64_t) v;
        } else if (g_strcmp0(tok[0], "cosim_marker") == 0 && tok[1]) {
            char *endp = NULL;
            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
            if (!endp || *endp != '\0') {
                fprintf(stderr, "hybrid_handoff: invalid cosim_marker=%s\n",
                        tok[1]);
                return -1;
            }
            cosim_marker_mode = (v != 0);
        } else if (g_strcmp0(tok[0], "cosim_counts") == 0 && tok[1]) {
            g_auto(GStrv) parts = g_strsplit(tok[1], ":", -1);
            size_t n = g_strv_length(parts);
            if (n == 0) {
                fprintf(stderr, "hybrid_handoff: empty cosim_counts\n");
                return -1;
            }
            cosim_counts = g_new0(uint64_t, n);
            for (size_t k = 0; k < n; k++) {
                char *endp = NULL;
                unsigned long long v = g_ascii_strtoull(parts[k], &endp, 0);
                if (parts[k][0] == '\0' || !endp || *endp != '\0') {
                    fprintf(stderr,
                            "hybrid_handoff: invalid cosim_counts entry: %s\n",
                            parts[k]);
                    return -1;
                }
                if (k > 0 && v <= cosim_counts[k - 1]) {
                    fprintf(stderr, "hybrid_handoff: cosim_counts must be "
                                    "strictly ascending\n");
                    return -1;
                }
                cosim_counts[k] = (uint64_t) v;
            }
            cosim_n_counts = n;
        } else if (g_strcmp0(tok[0], "drain_at_exit") == 0 && tok[1]) {
            // F14: any non-zero value enables. "1" is the canonical form
            // hsim emits; other ints (incl. negatives parsed as huge unsigned)
            // also enable -- the flag is a binary switch, not a count.
            char *endp = NULL;
            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
            if (!endp || *endp != '\0') {
                fprintf(stderr, "hybrid_handoff: invalid drain_at_exit=%s\n",
                        tok[1]);
                return -1;
            }
            drain_at_exit_mode = (v != 0);
        } else {
            fprintf(stderr, "hybrid_handoff: unknown option: %s\n", argv[i]);
            return -1;
        }
    }
    if (!outfile_path) {
        fputs("hybrid_handoff: outfile=PATH is required\n", stderr);
        return -1;
    }
    if (pc_mode) {
        fprintf(stderr,
                "hybrid_handoff: PC-mode enter=0x%" PRIx64 "\n",
                enter_pc_arg);
    }
    if (icount_mode) {
        fprintf(stderr,
                "hybrid_handoff: icount-mode target=%" PRIu64 "\n",
                icount_target);
    }
    if (bbv_mode) {
        if (bbv_slice_target == 0) {
            fputs("hybrid_handoff: bbv_out= requires slice=N\n", stderr);
            return -1;
        }
        bbv_emit = bbv_emit_new(bbv_out_path, bbv_slice_target);
        if (!bbv_emit) {
            fprintf(stderr, "hybrid_handoff: failed to open bbv_out=%s\n",
                    bbv_out_path);
            return -1;
        }
        fprintf(stderr,
                "hybrid_handoff: bbv-mode out=%s slice=%" PRIu64 "\n",
                bbv_out_path, bbv_slice_target);
    }
    if (slice_consume_mode) {
        if (bbv_slice_target == 0) {
            fputs("hybrid_handoff: slice_at= requires slice=N\n", stderr);
            return -1;
        }
        fprintf(stderr,
                "hybrid_handoff: slice-consume mode slice=%" PRIu64
                " slice_at=%" PRIu64 "\n",
                bbv_slice_target, slice_at_target);
    }
    if (drain_at_exit_mode) {
        fputs("hybrid_handoff: drain-at-exit mode enabled\n", stderr);
        qemu_plugin_register_atexit_cb(id, on_atexit, NULL);
    }
    if (exit_marker_mode || exit_pc_mode) {
        if ((exit_marker_mode && exit_pc_mode) || pc_mode || icount_mode
            || bbv_mode || slice_consume_mode || drain_at_exit_mode
            || cosim_marker_mode || cosim_pc_mode) {
            fputs("hybrid_handoff: oracle exit drain (exit_marker/exit_pc) "
                  "is exclusive with the other trigger modes\n", stderr);
            return -1;
        }
        if (exit_pc_mode) {
            fprintf(stderr,
                    "hybrid_handoff: oracle exit-drain mode exit_pc=0x%"
                    PRIx64 "\n", exit_pc_arg);
        } else {
            fputs("hybrid_handoff: oracle exit-drain mode (exit marker)\n",
                  stderr);
        }
        if (drain_pc_set) {
            fprintf(stderr, "hybrid_handoff: oracle drain_pc=0x%" PRIx64 "\n",
                    drain_pc_arg);
        }
    } else if (drain_pc_set) {
        fputs("hybrid_handoff: drain_pc requires oracle exit-drain mode "
              "(exit_marker/exit_pc)\n", stderr);
        return -1;
    }
    if (cosim_marker_mode || cosim_pc_mode) {
        if ((cosim_marker_mode && cosim_pc_mode) || pc_mode || icount_mode
            || bbv_mode || slice_consume_mode || drain_at_exit_mode) {
            fputs("hybrid_handoff: cosim mode (cosim_marker/cosim_pc) is "
                  "exclusive with the other trigger modes\n", stderr);
            return -1;
        }
        if (cosim_n_counts == 0) {
            fputs("hybrid_handoff: cosim mode requires cosim_counts=a:b:...\n",
                  stderr);
            return -1;
        }
        if (cosim_pc_mode) {
            fprintf(stderr,
                    "hybrid_handoff: cosim mode entry pc=0x%" PRIx64
                    ", %zu drain count(s)\n", cosim_pc_arg, cosim_n_counts);
        } else {
            fprintf(stderr,
                    "hybrid_handoff: cosim mode (entry marker), "
                    "%zu drain count(s)\n", cosim_n_counts);
        }
        // Fresh stream per run: the sink appends, so stale records from a
        // previous run would otherwise survive.
        g_autofree char *stream = g_strdup_printf("%s.ckpts", outfile_path);
        unlink(stream);
    } else if (cosim_n_counts != 0) {
        fputs("hybrid_handoff: cosim_counts requires cosim mode "
              "(cosim_marker/cosim_pc)\n", stderr);
        return -1;
    }

    if (lockstep_pc_mode) {
        if (pc_mode || icount_mode || bbv_mode || slice_consume_mode
            || drain_at_exit_mode || exit_marker_mode || exit_pc_mode
            || cosim_marker_mode || cosim_pc_mode) {
            fputs("hybrid_handoff: lockstep_pc is exclusive with the other "
                  "trigger modes\n", stderr);
            return -1;
        }
        // outfile IS the record stream in this mode; start it fresh.
        unlink(outfile_path);
        fprintf(stderr,
                "hybrid_handoff: lockstep mode, arm pc=0x%" PRIx64
                ", max records=%" PRIu64 " (0 = until exit), stream=%s\n",
                lockstep_pc_arg, lockstep_max, outfile_path);
    } else if (lockstep_max != 0) {
        fputs("hybrid_handoff: lockstep_max requires lockstep_pc\n", stderr);
        return -1;
    }

    vcpu_state = qemu_plugin_scoreboard_new(sizeof(VcpuRegs));
    qemu_plugin_register_vcpu_tb_trans_cb(id, vcpu_tb_trans);
    return 0;
}

